def _guided_discovery_input_snapshot(
    settings_values: Mapping[str, Any],
    *,
    apps_base: str = "",
) -> Dict[str, str]:
    """Return the bounded, read-only inputs the coordinator scanners require."""

    values = dict(settings_values or {})
    snapshot = {
        key: str(values.get(key) or "").strip()
        for key in _GUIDED_DISCOVERY_INPUT_KEYS
    }
    snapshot.update(
        platform=platform.system(),
        home=str(Path.home()),
        radio_apps_base_folder=str(apps_base or values.get("radio_apps_base_folder") or "").strip(),
    )
    return snapshot


def _merge_legacy_application_results(payload: Dict[str, Any]) -> None:
    """Preserve legacy path-result keys while discovery keeps app evidence separate."""

    result_groups = {
        "flrig": ("fast_results", "path_flrig"),
        "fldigi": ("fast_results", "path_fldigi"),
        "flmsg": ("fast_results", "path_flmsg"),
        "flamp": ("fast_results", "path_flamp"),
        "js8call": ("js8_results", "path_js8call"),
    }
    for candidate in tuple(payload.get("install_candidates") or ()):
        app_id = str(getattr(candidate, "app_id", "") or "").strip().casefold()
        target = result_groups.get(app_id)
        path = str(getattr(candidate, "path", "") or "").strip()
        if target is None or not path:
            continue
        group_name, result_key = target
        results = payload.setdefault(group_name, {})
        if not isinstance(results, dict) or result_key in results:
            continue
        results[result_key] = PathDetectionResult(
            key=result_key,
            label=str(getattr(candidate, "display_name", "") or app_id),
            path=path,
            confidence=str(getattr(candidate, "confidence", "") or "detected"),
            reason="Detected by the guided application scan.",
            exists=bool(getattr(candidate, "exists", False)),
            target_type=str(getattr(candidate, "target_type", "") or "file"),
        )


class _GpgKeyProbeWorker(QObject):
    """Run bounded GPG executable/key discovery away from the GUI thread."""

    finished = Signal(int, object)

    def __init__(self, generation: int, configured_path: str) -> None:
        super().__init__()
        self.generation = int(generation)
        self.configured_path = str(configured_path or "").strip()

    def run(self) -> None:
        payload: Dict[str, object] = {
            "available": False,
            "message": "",
            "resolved": "",
            "public_keys": tuple(),
            "public_error": "",
            "secret_keys": tuple(),
            "secret_error": "",
        }
        try:
            ok, message, resolved = gpg_available(self.configured_path)
            payload.update(available=bool(ok), message=str(message or ""), resolved=str(resolved or ""))
            if ok:
                public_keys, public_error = list_public_keys(configured_path=self.configured_path)
                secret_keys, secret_error = list_secret_keys(configured_path=self.configured_path)
                payload.update(
                    public_keys=tuple(public_keys),
                    public_error=str(public_error or ""),
                    secret_keys=tuple(secret_keys),
                    secret_error=str(secret_error or ""),
                )
        except Exception as exc:
            payload["message"] = str(exc)
        self.finished.emit(self.generation, payload)


# A discovery operation that outlives the bounded application-shutdown wait
# must retain its Python wrappers until Qt reports that its thread ended. This
# prevents ``QThread: Destroyed while thread is still running`` without ever
# extending the UI-thread wait indefinitely.
_DETACHED_SOFTWARE_AUTOFILL_JOBS: Dict[int, Tuple[QThread, QObject]] = {}
_DETACHED_GPG_PROBE_JOBS: Dict[int, Tuple[QThread, QObject]] = {}


def _release_detached_software_autofill_job(job_id: int) -> None:
    _DETACHED_SOFTWARE_AUTOFILL_JOBS.pop(int(job_id), None)


def _release_detached_gpg_probe_job(job_id: int) -> None:
    _DETACHED_GPG_PROBE_JOBS.pop(int(job_id), None)


class SettingsTab(QWidget):
    """
    Global settings for CommsPlan.

    - Call sign / Name / State
    - Control mode
    - JS8Call TCP port
    - Primary JS8Call groups
    - JS8Call DIRECTED.TXT path
    - Radio software paths

    Timezone is *not* user selectable here; it is auto-detected from the
    system clock and stored under the 'timezone' key in SettingsManager.
    All entries are saved to config when:
      - The Save button is clicked, OR
      - The application exits (QApplication.aboutToQuit).

    Persistence is done via SettingsManager.set(...) when available,
    or by updating SettingsManager._data as a fallback. We *do not*
    call any .write() or .save() here to avoid AttributeError.
    """

    _CONTROL_LAUNCH_STATUS_KEYS = frozenset(("FLRig", "RigCtlD", "JS8Call_API"))

    settings_saved = Signal()
    appearance_changed = Signal()
    device_profiles_changed = Signal()
    operating_groups_changed = Signal()
    local_net_profiles_changed = Signal()
    open_logs_requested = Signal()
    log_level_changed = Signal(str)
    mesh_channel_refresh_requested = Signal(str)
    mesh_channel_cancel_requested = Signal(str, str)
    mesh_channel_configure_requested = Signal(str, str, dict)
    mesh_channel_remove_device_requested = Signal(str, str)
    mesh_connect_requested = Signal(str)
    mesh_disconnect_requested = Signal()
    # The eventual receiver-control service subscribes from its worker/lane to
    # this request.  Settings itself must only emit the immutable draft; it
    # must never open an endpoint or perform a probe in the Qt event handler.
    receiver_control_test_requested = Signal(dict)
    receiver_control_test_completed = Signal(dict)
    # Native VarAC preparation/application is deliberately host-worker owned.
    # These cache-only payload relays let the integration layer provide that
    # worker without letting Settings rendering or typing inspect native files.
    varac_native_prepare_requested = Signal(object)
    varac_native_apply_requested = Signal(object)
    # Python object ids are pointer-width values and may exceed Qt's 32-bit
    # ``int`` signal type on 64-bit platforms.
    _guided_radio_autofill_finished = Signal(object, object)
    _guided_radio_autofill_failed = Signal(object, str)
    _guided_radio_autofill_released = Signal(object)
    _guided_native_config_finished = Signal(object, object)
    _guided_native_config_failed = Signal(object, str)
    _guided_native_config_released = Signal(object)
    _varac_native_job_finished = Signal(object, object)
    _varac_native_job_failed = Signal(object, str)
    _varac_native_job_released = Signal(object)
    _multi_rig_preview_finished = Signal(object, object)
    _multi_rig_preview_failed = Signal(object, str)
    _multi_rig_preview_released = Signal(object)
    SECTION_HEALTH_STATE_ROLE = int(Qt.UserRole) + 1
    SECTION_HEALTH_KEY_ROLE = int(Qt.UserRole) + 2
    SECTION_STACK_INDEX_ROLE = int(Qt.UserRole) + 3
    SECTION_SCOPE_ROLE = int(Qt.UserRole) + 4

    def set_receiver_control_test_service_ready(self, ready: bool) -> None:
        """Declare that an asynchronous receiver-test service is installed.

        SDR-1 deliberately ships this as an opt-in seam.  No service is
        installed by Settings, so the setup dialog keeps Test control disabled
        rather than creating an endpoint connection on the UI thread.
        """

        self._receiver_control_test_service_ready = bool(ready)

    def _receiver_control_test_service_is_ready(self) -> bool:
        """Return cached service availability only; never discover a receiver."""

        return bool(getattr(self, "_receiver_control_test_service_ready", False))

