        def _make_support_card(title: str, status_object_name: str) -> tuple[QFrame, QLabel, QLabel]:
            card = QFrame()
            card.setFrameShape(QFrame.StyledPanel)
            card_layout = QVBoxLayout(card)
            card_layout.setContentsMargins(12, 10, 12, 10)
            card_layout.setSpacing(6)
            title_label = QLabel(title)
            title_font = title_label.font()
            title_font.setBold(True)
            title_label.setFont(title_font)
            card_layout.addWidget(title_label)
            status_label = QLabel()
            status_label.setObjectName(status_object_name)
            status_label.setWordWrap(True)
            card_layout.addWidget(status_label)
            return card, title_label, status_label

        def _make_radio_profile_dashboard_section(title: str, content: QWidget, *, checked: bool = True) -> QGroupBox:
            section = QGroupBox(title)
            section.setCheckable(True)
            section.setChecked(bool(checked))
            section.setToolTip(f"Show or hide the {title} section.")
            section.setAccessibleName(f"{title} section")
            section.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Preferred)
            section_layout = QVBoxLayout(section)
            section_layout.setContentsMargins(10, 10, 10, 12)
            section_layout.setSpacing(6)
            section_layout.addWidget(content)
            # A visible parentless QWidget becomes a native top-level window
            # on Windows. Parent the content before applying its initial state.
            content.setVisible(bool(checked))
            section.toggled.connect(content.setVisible)
            return section

        def _style_radio_profile_form(form: QFormLayout) -> None:
            form.setContentsMargins(0, 0, 0, 0)
            form.setSpacing(8)
            form.setFieldGrowthPolicy(QFormLayout.ExpandingFieldsGrow)
            form.setFormAlignment(Qt.AlignTop | Qt.AlignLeft)
            form.setLabelAlignment(Qt.AlignTop | Qt.AlignLeft)

        def _make_radio_profile_detail_grid() -> Tuple[QWidget, QGridLayout]:
            widget = QWidget()
            layout = QGridLayout(widget)
            layout.setContentsMargins(0, 0, 0, 0)
            layout.setHorizontalSpacing(10)
            layout.setVerticalSpacing(6)
            layout.setAlignment(Qt.AlignTop | Qt.AlignLeft)
            layout.setColumnStretch(1, 1)
            return widget, layout

        def _add_radio_profile_detail_row(layout: QGridLayout, row: int, label_text: str, value_label: QLabel) -> None:
            label = QLabel(label_text)
            label.setAlignment(Qt.AlignTop | Qt.AlignLeft)
            label.setSizePolicy(QSizePolicy.Fixed, QSizePolicy.Preferred)
            value_label.setAlignment(Qt.AlignTop | Qt.AlignLeft)
            value_label.setWordWrap(True)
            value_label.setMinimumHeight(max(value_label.sizeHint().height(), value_label.fontMetrics().lineSpacing() + 6))
            value_label.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Preferred)
            layout.addWidget(label, row, 0)
            layout.addWidget(value_label, row, 1)

