    def _detect_migration_roles(self) -> set[str]:
        roles: set[str] = set()
        message_paths = self.settings.get("message_paths", {}) or {}
        if self._configured_text("path_flrig") or self._configured_text("path_fldigi") or self._configured_text("fldigi_log_path"):
            roles.add("fast_light")
        if self._configured_text("path_js8call") or self._configured_text("js8_directed_path"):
            roles.add("js8call")
        if self._configured_text("path_js8spotter"):
            roles.add("js8spotter")
        if self._configured_text("varac_path") or self._configured_text("varac_launch_cmd") or str(message_paths.get("varac", "") or "").strip():
            roles.add("varac")
        if self._configured_text("path_flamp") or str(message_paths.get("flamp", "") or "").strip():
            roles.add("flamp")
        if self._configured_text("path_flmsg") or str(message_paths.get("flmsg", "") or "").strip():
            roles.add("flmsg")
        if self._configured_text("path_commstat"):
            roles.add("commstat")
        return roles

    def _start_multi_rig_setup(self) -> bool:
        status = self._current_multi_rig_runtime_status()
        if status.startup_mode in {STARTUP_FRESH_DEFAULT_READY, STARTUP_MIGRATED}:
            self._select_settings_section_group(getattr(self, "radio_profile_section_group", None))
            return True

        dialog = QDialog(self)
        dialog.setWindowTitle("Upgrade Existing Station")
        dialog.resize(620, 520)
        layout = QVBoxLayout(dialog)
        intro = QLabel(
            "CommsPlan found your existing single-radio station. Review the radio identity and detected software below. "
            "CommsPlan will create and verify a backup before upgrading the station."
        )
        intro.setWordWrap(True)
        layout.addWidget(intro)

        form = QFormLayout()
        form.setFieldGrowthPolicy(QFormLayout.ExpandingFieldsGrow)
        layout.addLayout(form)

        catalog_payload = self._multi_rig_radio_catalog()
        catalog_entries = list(catalog_payload.get("entries", []) or [])
        model_combo = QComboBox()
        model_combo.setEditable(True)
        model_combo.setInsertPolicy(QComboBox.NoInsert)
        for entry in catalog_entries:
            model_combo.addItem(str(entry.get("display_name", "") or ""), dict(entry))
        if model_combo.count() == 0:
            model_combo.addItem("Manual entry", {})
        model_combo.setMinimumWidth(320)
        form.addRow("Radio model:", model_combo)

        manual_chk = QCheckBox("Use manual model entry")
        if not catalog_entries:
            manual_chk.setChecked(True)
            model_combo.setEnabled(False)
        form.addRow("", manual_chk)
        manufacturer_edit = QLineEdit()
        model_edit = QLineEdit()
        form.addRow("Manufacturer:", manufacturer_edit)
        form.addRow("Model:", model_edit)
        name_edit = QLineEdit()
        name_edit.setPlaceholderText("Example: IC-7300 HF Desk")
        form.addRow("Display name:", name_edit)
        plan_edit = QLineEdit("Daily HF Schedule")
        form.addRow("Plan name:", plan_edit)
        display_name_user_edited = False
        last_catalog_display_name = ""

        role_group = QGroupBox("Software CommsPlan found in Configuration")
        role_layout = QVBoxLayout(role_group)
        role_layout.setSpacing(4)
        role_checks: Dict[str, QCheckBox] = {}
        role_labels = [
            ("fast_light", "FLRig / FLDigi (Fast Light)"),
            ("js8call", "JS8Call"),
            ("js8spotter", "CommsPlan Spotter"),
            ("varac", "VarAC"),
            ("flamp", "FLAMP"),
            ("flmsg", "FLMsg"),
            ("commstat", "CommStat"),
        ]
        detected_roles = self._detect_migration_roles()
        for role, label in role_labels:
            chk = QCheckBox(label)
            chk.setChecked(role in detected_roles)
            role_layout.addWidget(chk)
            role_checks[role] = chk
        role_note = QLabel("These choices come from configured paths and endpoints, not from live process checks.")
        role_note.setWordWrap(True)
        role_layout.addWidget(role_note)
        layout.addWidget(role_group)

        def _selected_catalog_entry() -> Dict[str, Any]:
            current_text = model_combo.currentText().strip()
            current_index = model_combo.currentIndex()
            if current_index < 0 or current_text != model_combo.itemText(current_index).strip():
                return {}
            data = model_combo.currentData()
            return dict(data) if isinstance(data, dict) else {}

        def _sync_model_fields() -> None:
            nonlocal display_name_user_edited, last_catalog_display_name
            manual = bool(manual_chk.isChecked())
            entry = _selected_catalog_entry()
            manufacturer_edit.setEnabled(manual)
            model_edit.setEnabled(manual)
            if not manual:
                manufacturer_edit.setText(str(entry.get("manufacturer", "") or ""))
                model_edit.setText(str(entry.get("model_name", "") or ""))
                display_name = str(entry.get("display_name", "") or "").strip()
                current_name = name_edit.text().strip()
                can_replace = (
                    not current_name
                    or current_name == last_catalog_display_name
                    or not display_name_user_edited
                )
                if display_name and can_replace:
                    name_edit.setText(display_name)
                    last_catalog_display_name = display_name
                    display_name_user_edited = False

        def _mark_display_name_user_edited(_text: str) -> None:
            nonlocal display_name_user_edited
            display_name_user_edited = True

        model_combo.currentIndexChanged.connect(lambda _idx: _sync_model_fields())
        manual_chk.stateChanged.connect(lambda _state: _sync_model_fields())
        name_edit.textEdited.connect(_mark_display_name_user_edited)
        _sync_model_fields()

        buttons = QDialogButtonBox()
        setup_btn = buttons.addButton("Back Up and Upgrade Station", QDialogButtonBox.AcceptRole)
        exit_btn = buttons.addButton("Exit CommsPlan", QDialogButtonBox.RejectRole)
        layout.addWidget(buttons)

        def _accept_setup() -> None:
            if not name_edit.text().strip():
                QMessageBox.warning(dialog, "Upgrade Existing Station", "Radio display name is required.")
                return
            if manual_chk.isChecked() and (
                not manufacturer_edit.text().strip() or not model_edit.text().strip()
            ):
                QMessageBox.warning(
                    dialog,
                    "Upgrade Existing Station",
                    "Manufacturer and model are required for manual radio entry.",
                )
                return
            if not manual_chk.isChecked() and not _selected_catalog_entry():
                QMessageBox.warning(
                    dialog,
                    "Upgrade Existing Station",
                    "Choose a supported radio model from the list, or select manual model entry.",
                )
                return
            dialog.accept()

        setup_btn.clicked.connect(_accept_setup)
        exit_btn.clicked.connect(dialog.reject)
        buttons.rejected.connect(dialog.reject)
        if dialog.exec() != QDialog.Accepted:
            return False

        roles = tuple(sorted(role for role, chk in role_checks.items() if chk.isChecked()))
        migration_settings = self._settings_values_for_migration()
        return self._run_backup_backed_multi_rig_setup_apply(
            migration_settings=migration_settings,
            radio_name=name_edit.text().strip(),
            radio_manufacturer=manufacturer_edit.text().strip(),
            radio_model=model_edit.text().strip(),
            operating_plan_name=plan_edit.text().strip(),
            enabled_software_roles=roles,
        )

    def _set_multi_rig_setup_preview_text(self, text: str, tooltip: str = "") -> None:
        if not hasattr(self, "multi_rig_autoconfig_preview_label"):
            return
        self.multi_rig_autoconfig_preview_label.setText(text)
        self.multi_rig_autoconfig_preview_label.setToolTip(tooltip or text)
        self.multi_rig_autoconfig_preview_label.setVisible(bool(text.strip()))

    def _run_backup_backed_multi_rig_setup_apply(
        self,
        *,
        migration_settings: Mapping[str, Any],
        radio_name: str,
        radio_manufacturer: str,
        radio_model: str,
        operating_plan_name: str,
        enabled_software_roles: Sequence[str],
    ) -> bool:
        apply_plan = build_single_rig_upgrade_apply_plan(
            migration_settings,
            radio_name=radio_name,
            operating_plan_name=operating_plan_name,
            config_dir=get_config_dir(),
            extra_backup_paths=self._multi_rig_autoconfig_extra_app_paths(migration_settings),
        )
        if not apply_plan.can_apply:
            detail = "\n".join(apply_plan.blockers)
            self._set_multi_rig_setup_preview_text(
                f"Station upgrade is blocked until backup readiness is resolved.\n{detail}".strip(),
                detail,
            )
            self._publish_settings_action_feedback(
                status="blocked",
                summary="Station upgrade blocked: backup readiness needs review.",
                detail=detail,
                action_type="configure_automatically",
                source_surface="settings.configure_automatically.multirig.apply",
            )
            QMessageBox.warning(self, "Upgrade Existing Station", detail)
            return False
        try:
            backup_result = create_config_backup(apply_plan.backup_paths, reason=apply_plan.backup_reason)
        except Exception as exc:
            log.exception("Failed creating Multi-Rig migration backup.")
            detail = str(exc) or exc.__class__.__name__
            self._set_multi_rig_setup_preview_text(
                f"Station upgrade is blocked because the backup could not be created.\n{detail}".strip(),
                detail,
            )
            self._publish_settings_action_feedback(
                status="failed",
                summary="Station upgrade blocked: backup could not be created.",
                detail=detail,
                action_type="configure_automatically",
                source_surface="settings.configure_automatically.multirig.apply",
            )
            QMessageBox.warning(self, "Upgrade Existing Station", detail)
            return False
        failed_backup_items = tuple(item for item in backup_result.items if item.status == "failed")
        primary_backup_ok = bool(backup_result.items and backup_result.items[0].status == "backed_up")
        if failed_backup_items or not primary_backup_ok:
            detail_parts = [f"{item.original_path}: {item.error or item.status}" for item in failed_backup_items]
            if not primary_backup_ok:
                detail_parts.insert(0, "Primary CommsPlan configuration backup did not complete.")
            detail = "\n".join(detail_parts)
            self._set_multi_rig_setup_preview_text(
                f"Station upgrade is blocked because the backup did not complete.\n{detail}".strip(),
                detail,
            )
            self._publish_settings_action_feedback(
                status="blocked",
                summary="Station upgrade blocked: backup did not complete.",
                detail=detail,
                action_type="configure_automatically",
                source_surface="settings.configure_automatically.multirig.apply",
            )
            QMessageBox.warning(self, "Upgrade Existing Station", detail)
            return False
        self._publish_settings_action_feedback(
            status="succeeded",
            summary="Station upgrade backup created.",
            detail=f"Backup saved to {backup_result.backup_dir}",
            action_type="configure_automatically",
            source_surface="settings.configure_automatically.multirig.apply",
        )
        try:
            with self.multi_radio_store.connect() as conn:
                result = ensure_multi_rig_migration(
                    conn,
                    migration_settings,
                    radio_name=radio_name,
                    radio_manufacturer=radio_manufacturer,
                    radio_model=radio_model,
                    operating_plan_name=operating_plan_name,
                    enabled_software_roles=enabled_software_roles,
                )
        except Exception as exc:
            log.exception("Failed running multi-rig migration.")
            detail = str(exc) or exc.__class__.__name__
            self._set_multi_rig_setup_preview_text(
                f"Station upgrade could not be completed after backup.\n{detail}".strip(),
                detail,
            )
            self._publish_settings_action_feedback(
                status="failed",
                summary="Station upgrade failed after backup.",
                detail=detail,
                action_type="configure_automatically",
                source_surface="settings.configure_automatically.multirig.apply",
            )
            QMessageBox.warning(self, "Upgrade Existing Station", f"Unable to upgrade the station:\n{exc}")
            return False
        if not result.applied and not result.already_current:
            self._set_multi_rig_setup_preview_text(
                "Station upgrade could not be completed. Your current settings were left unchanged."
            )
            self._publish_settings_action_feedback(
                status="failed",
                summary="Station upgrade failed after backup.",
                detail="CommsPlan could not complete the station upgrade. Your current settings were left unchanged.",
                action_type="configure_automatically",
                source_surface="settings.configure_automatically.multirig.apply",
            )
            QMessageBox.warning(
                self,
                "Upgrade Existing Station",
                "CommsPlan could not complete the station upgrade. Your current settings were left unchanged.",
            )
            return False
        self._refresh_multi_radio_tables(refresh_section_titles=False)
        self._refresh_cached_multi_rig_runtime_status()
        self._emit_device_profiles_changed()
        self._set_multi_rig_setup_preview_text(
            f"Station upgrade is complete. Backup saved to {backup_result.backup_dir}",
            f"Backup manifest: {backup_result.manifest_path}",
        )
        self._publish_settings_action_feedback(
            status="succeeded",
            summary="Station upgrade is complete.",
            detail=f"CommsPlan created the first runtime radio after backing up settings to {backup_result.backup_dir}",
            action_type="configure_automatically",
            source_surface="settings.configure_automatically.multirig.apply",
        )
        return True
    def _update_device_profile_readiness_detail(
        self,
        readiness_report: Any | None = None,
        focused_radio_id: int | None = None,
    ) -> None:
        if not hasattr(self, "device_profile_detail_label"):
            return

        def _set_readiness_card_style(level: str) -> None:
            if not hasattr(self, "device_profile_readiness_card"):
                return
            theme = resolve_theme(self.settings)
            level_key = (level or "info").strip().lower()
            color_map = {
                "success": theme.get("success", "#2E7D32"),
                "warning": theme.get("warning", "#C99700"),
                "danger": theme.get("danger", "#C62828"),
                "info": theme.get("info", theme.get("accent", "#1565C0")),
            }
            accent = QColor(color_map.get(level_key, color_map["info"]))
            bg = QColor(accent)
            bg.setAlpha(24)
            border = QColor(accent)
            border.setAlpha(140)
            text_color = theme.get("text", "#1C1F21")
            muted_color = theme.get("text_muted", text_color)
            self.device_profile_readiness_card.setStyleSheet(
                "QFrame {"
                f" background-color: {bg.name(QColor.HexArgb)};"
                f" border: 1px solid {border.name(QColor.HexArgb)};"
                " border-radius: 8px;"
                "}"
                f" QLabel {{ color: {text_color}; border: none; background: transparent; }}"
                f" QLabel#deviceProfileReadinessStatus {{ color: {muted_color}; }}"
            )

        if hasattr(self, "device_profile_readiness_status_label"):
            self.device_profile_readiness_status_label.setObjectName("deviceProfileReadinessStatus")
        if hasattr(self, "device_profile_guardrail_status_label"):
            self.device_profile_guardrail_status_label.setObjectName("deviceProfileGuardrailStatus")
        if readiness_report is None:
            readiness_report = self._current_station_readiness_report()
        else:
            self._last_station_readiness_report = readiness_report
        if focused_radio_id is None:
            focused_radio_id = self._current_device_profile_focus_id()
        if not focused_radio_id:
            if hasattr(self, "device_profile_readiness_card"):
                self.device_profile_readiness_card.setVisible(True)
            message = "Select a radio to review the readiness checklist for that radio."
            if hasattr(self, "device_profile_detail_title_label"):
                self.device_profile_detail_title_label.setText("Selected Radio")
            if hasattr(self, "device_profile_readiness_title_label"):
                self.device_profile_readiness_title_label.setText("Focused Radio Readiness")
            if hasattr(self, "device_profile_readiness_status_label"):
                self.device_profile_readiness_status_label.setText(message)
            self._set_device_profile_guardrail_status(())
            self._refresh_device_profile_status_chips(None, readiness_report)
            self._refresh_radio_profile_connection_details(None)
            self._refresh_radio_profile_frequency_timer_details(None)
            self._refresh_radio_profile_optional_groups(None)
            self._refresh_radio_profile_inventory_details(None)
            self._refresh_radio_profile_identity_inline_controls(None)
            self._refresh_radio_profile_connection_shortcuts(None, readiness_report)
            self._refresh_radio_profile_software_flag_controls(None)
            self._refresh_radio_profile_software_chips(readiness_report)
            self._refresh_radio_profile_stack_guidance(readiness_report, None, None)
            self._refresh_radio_profile_guided_task_buttons(None, readiness_report)
            self._select_radio_profile_guided_task(getattr(self, "radio_profile_guided_task_key", "review"), scroll=False)
            self.device_profile_detail_label.setText("Select a radio to edit that radio's settings.")
            _set_readiness_card_style("info")
            return
        profile = self._device_profile_by_id(int(focused_radio_id))
        if not profile:
            message = "Select a radio to review the readiness checklist for that radio."
            if hasattr(self, "device_profile_detail_title_label"):
                self.device_profile_detail_title_label.setText("Selected Radio")
            if hasattr(self, "device_profile_readiness_title_label"):
                self.device_profile_readiness_title_label.setText("Focused Radio Readiness")
            if hasattr(self, "device_profile_readiness_status_label"):
                self.device_profile_readiness_status_label.setText(message)
            self._set_device_profile_guardrail_status(())
            self._refresh_device_profile_status_chips(None, readiness_report)
            self._refresh_radio_profile_connection_details(None)
            self._refresh_radio_profile_frequency_timer_details(None)
            self._refresh_radio_profile_optional_groups(None)
            self._refresh_radio_profile_inventory_details(None)
            self._refresh_radio_profile_identity_inline_controls(None)
            self._refresh_radio_profile_connection_shortcuts(None, readiness_report)
            self._refresh_radio_profile_software_flag_controls(None)
            self._refresh_radio_profile_software_chips(readiness_report)
            self._refresh_radio_profile_stack_guidance(readiness_report, None, None)
            self._refresh_radio_profile_guided_task_buttons(None, readiness_report)
            self._select_radio_profile_guided_task(getattr(self, "radio_profile_guided_task_key", "review"), scroll=False)
            self.device_profile_detail_label.setText("Select a radio to edit that radio's settings.")
            _set_readiness_card_style("info")
            return
        summary = readiness_report.summary_for_radio(int(focused_radio_id))
        guardrail_warnings = self._current_multi_rig_guardrail_messages()
        has_guardrail_warnings = self._set_device_profile_guardrail_status(guardrail_warnings)
        assignment = self._effective_assignment_map().get(int(focused_radio_id), {})
        name = str(profile.get("name", "") or "Radio").strip() or "Radio"
        assignment_name = str(assignment.get("operating_profile_name", "") or "").strip() or "Unassigned"
        assignment_state = str(assignment.get("assignment_state", "") or "").strip().lower()
        if hasattr(self, "device_profile_readiness_title_label"):
            self.device_profile_readiness_title_label.setText(f"{name} Readiness")
        if hasattr(self, "device_profile_detail_title_label"):
            self.device_profile_detail_title_label.setText(f"{name} Profile")
        self._refresh_device_profile_status_chips(profile, readiness_report)
        self._refresh_radio_profile_connection_details(profile)
        self._refresh_radio_profile_frequency_timer_details(profile)
        self._refresh_radio_profile_optional_groups(profile)
        self._refresh_radio_profile_inventory_details(profile)
        self._refresh_radio_profile_identity_inline_controls(profile)
        self._refresh_radio_profile_connection_shortcuts(profile, readiness_report)
        self._refresh_radio_profile_software_flag_controls(profile)
        self._refresh_radio_profile_software_chips(readiness_report)
        self._refresh_radio_profile_stack_guidance(readiness_report, int(focused_radio_id), profile)
        self._refresh_radio_profile_guided_task_buttons(profile, readiness_report)
        self._select_radio_profile_guided_task(getattr(self, "radio_profile_guided_task_key", "review"), scroll=False)
        self.device_profile_detail_label.setText(self._selected_radio_detail_text(profile, readiness_report))
        if summary is None or (
            summary.required_count <= 0 and summary.recommended_count <= 0 and summary.informational_count <= 0
        ):
            if self._profile_needs_operator_name(profile):
                if hasattr(self, "device_profile_readiness_card"):
                    self.device_profile_readiness_card.setVisible(True)
                message = f"{name} is using a fallback name. Rename it so radio-specific settings are easy to recognize."
                if hasattr(self, "device_profile_readiness_status_label"):
                    self.device_profile_readiness_status_label.setText(message)
                _set_readiness_card_style("warning")
                return
            if hasattr(self, "device_profile_readiness_card"):
                self.device_profile_readiness_card.setVisible(bool(has_guardrail_warnings))
            assigned_model = self._assignment_display_text(assignment_name, assignment_state)
            model_text = (
                f" Assigned model: {assigned_model}."
                if assignment_name != "Unassigned"
                else " No operating model is currently assigned."
            )
            message = f"{name} is ready.{model_text}"
            if hasattr(self, "device_profile_readiness_status_label"):
                self.device_profile_readiness_status_label.setText(message)
            _set_readiness_card_style("warning" if has_guardrail_warnings else "success")
            return
        if hasattr(self, "device_profile_readiness_card"):
            self.device_profile_readiness_card.setVisible(True)
        issue_lines = []
        for issue in readiness_report.issues:
            if int(issue.radio_id or 0) != int(focused_radio_id):
                continue
            issue_lines.append(format_readiness_issue(issue))
        detail_text = " | ".join(issue_lines[:4])
        if len(issue_lines) > 4:
            detail_text += f" | {len(issue_lines) - 4} more item(s)"
        assigned_model = self._assignment_display_text(assignment_name, assignment_state)
        model_text = (
            f"Assigned model: {assigned_model}. "
            if assignment_name != "Unassigned"
            else "No operating model is currently assigned. "
        )
        message = f"{readiness_summary_status_text(summary, subject=name)} {model_text}".strip()
        detail_message = readiness_state_description(summary.overall_state)
        if detail_text:
            detail_message = f"{detail_message} Guidance: {detail_text}"
        if hasattr(self, "device_profile_readiness_status_label"):
            if self._profile_needs_operator_name(profile):
                detail_message = (
                    f"Rename this radio so radio-specific settings are easy to recognize. {detail_message}"
                )
            self.device_profile_readiness_status_label.setText(f"{message}\n{detail_message}")
        self.device_profile_detail_label.setText(self._selected_radio_detail_text(profile, readiness_report))
        _set_readiness_card_style(readiness_state_card_level(summary.overall_state))

    def _set_guidance_card_state(
        self,
        card: QWidget,
        title_label: QLabel,
        status_label: QLabel,
        *,
        title: str,
        text: str,
        level: str,
    ) -> None:
        theme = resolve_theme(self.settings)
        level_key = (level or "info").strip().lower()
        color_map = {
            "success": theme.get("success", "#2E7D32"),
            "warning": theme.get("warning", "#C99700"),
            "danger": theme.get("danger", "#C62828"),
            "info": theme.get("info", theme.get("accent", "#1565C0")),
        }
        accent = QColor(color_map.get(level_key, color_map["info"]))
        bg = QColor(accent)
        bg.setAlpha(24)
        border = QColor(accent)
        border.setAlpha(140)
        text_color = theme.get("text", "#1C1F21")
        muted_color = theme.get("text_muted", text_color)
        title_label.setText(title)
        status_label.setText(text)
        card.setStyleSheet(
            "QFrame {"
            f" background-color: {bg.name(QColor.HexArgb)};"
            f" border: 1px solid {border.name(QColor.HexArgb)};"
            " border-radius: 8px;"
            "}"
            f" QLabel {{ color: {text_color}; border: none; background: transparent; }}"
            f" QLabel#{status_label.objectName()} {{ color: {muted_color}; }}"
        )

    def _build_readiness_summary_text(self) -> str:
        report = self._current_station_readiness_report()
        lines = [readiness_report_detail_text(report, title="CommsPlan Multi-Rig Readiness Summary")]
        lines.extend(
            [
                (
                    f"Issues: {int(report.required_count)} required, "
                    f"{int(report.recommended_count)} recommended, "
                    f"{int(report.informational_count)} informational"
                ),
            ]
        )
        global_issues = [issue for issue in report.issues if issue.scope == "global"]
        if global_issues:
            lines.append("")
            lines.append("Station Guidance:")
            for issue in global_issues:
                lines.append(f"- {format_readiness_issue(issue)}")
        if report.radio_summaries:
            lines.append("")
            lines.append("Radio Guidance:")
            for summary in report.radio_summaries:
                lines.append(f"- {summary.name}: {readiness_state_label(summary.overall_state)}")
                lines.append(f"  {readiness_summary_status_text(summary, subject=summary.name)}")
                for message in summary.messages[:3]:
                    lines.append(f"  - {message}")
        return "\n".join(lines)

    def _copy_readiness_summary(self) -> None:
        text = self._build_readiness_summary_text()
        QApplication.clipboard().setText(text)
        if hasattr(self, "copy_readiness_summary_btn"):
            QToolTip.showText(
                self.copy_readiness_summary_btn.mapToGlobal(self.copy_readiness_summary_btn.rect().bottomLeft()),
                "Readiness summary copied to clipboard.",
                self.copy_readiness_summary_btn,
            )

    def _current_operating_profile_focus_id(self) -> int | None:
        if not hasattr(self, "operating_profiles_table"):
            return None
        item = self.operating_profiles_table.currentItem()
        if item is not None:
            row_item = self.operating_profiles_table.item(item.row(), 2)
            if row_item is not None:
                try:
                    ident = int(row_item.data(Qt.UserRole) or 0)
                except Exception:
                    ident = 0
                if ident > 0:
                    return ident
        first = next(
            (
                int(row.get("id", 0) or 0)
                for row in self.operating_profiles
                if isinstance(row, dict) and int(row.get("id", 0) or 0) > 0
            ),
            0,
        )
        return first or None

    def _update_operating_profile_guidance_detail(self) -> None:
        if not hasattr(self, "operating_profiles_guidance_card"):
            return
        focused_id = self._current_operating_profile_focus_id()
        if not focused_id:
            self._set_guidance_card_state(
                self.operating_profiles_guidance_card,
                self.operating_profiles_guidance_title_label,
                self.operating_profiles_guidance_status_label,
                title="Focused Operating Model Guidance",
                text="Add an operating model to define which CommsPlan features and scheduler behavior apply to an assigned radio schedule.",
                level="info",
            )
            return
        profile = self._operating_profile_by_id(int(focused_id))
        if not profile:
            return
        name = str(profile.get("name", "") or "Operating Model").strip() or "Operating Model"
        assigned_rows = [
            row
            for row in self.device_assignments
            if isinstance(row, dict) and int(row.get("operating_profile_id", 0) or 0) == int(focused_id)
        ]
        assigned_devices = [str(row.get("device_name", "") or "Radio").strip() for row in assigned_rows[:3]]
        if int(profile.get("enabled", 1) or 0) != 1:
            text = (
                f"{name} is disabled. Enable it before using it for a radio. "
                f"Workflow preset is {self._scheduler_mode_label(profile.get('scheduler_mode', 'full'))}."
            )
            level = "warning"
        else:
            shell_summary = self._operating_profile_shell_summary(profile)
            if assigned_rows:
                text = (
                f"{name} is currently assigned to {len(assigned_rows)} radio"
                    f"{'s' if len(assigned_rows) != 1 else ''}: {', '.join(assigned_devices)}. "
                    f"CommsPlan features: {shell_summary}."
                )
                level = "success"
            else:
                text = (
                    f"{name} is ready to use. "
                    f"Workflow preset: {self._scheduler_mode_label(profile.get('scheduler_mode', 'full'))}. "
                    f"CommsPlan features: {shell_summary}."
                )
                level = "info"
        self._set_guidance_card_state(
            self.operating_profiles_guidance_card,
            self.operating_profiles_guidance_title_label,
            self.operating_profiles_guidance_status_label,
            title=f"{name} Guidance",
            text=text,
            level=level,
        )

    def _current_device_assignment_focus_id(self) -> int | None:
        if not hasattr(self, "device_assignments_table"):
            return None
        item = self.device_assignments_table.currentItem()
        if item is not None:
            row_item = self.device_assignments_table.item(item.row(), 3)
            if row_item is not None:
                try:
                    ident = int(row_item.data(Qt.UserRole) or 0)
                except Exception:
                    ident = 0
                if ident > 0:
                    return ident
        first = next(
            (
                int(row.get("device_profile_id", 0) or 0)
                for row in self.device_assignments
                if isinstance(row, dict) and int(row.get("device_profile_id", 0) or 0) > 0
            ),
            0,
        )
        return first or None

    def _update_device_assignments_guidance_detail(self) -> None:
        if not hasattr(self, "device_assignments_guidance_card"):
            return
        focused_id = self._current_device_assignment_focus_id()
        active_swap = dict(self.active_profile_swap or {})
        if not focused_id:
            text = "Operating Model Assignment connects radios to the CommsPlan behavior model they should use. Select a row to review whether that radio is using its normal model or a temporary override."
            if active_swap:
                text = (
                    "A temporary model swap is active. Review the focused assignment rows and use Restore Swap when the temporary Station Default handoff is no longer needed."
                )
            self._set_guidance_card_state(
                self.device_assignments_guidance_card,
                self.device_assignments_guidance_title_label,
                self.device_assignments_guidance_status_label,
                title="Focused Operating Model Assignment Guidance",
                text=text,
                level="warning" if active_swap else "info",
            )
            return
        row = next(
            (
                dict(item)
                for item in self.device_assignments
                if isinstance(item, dict) and int(item.get("device_profile_id", 0) or 0) == int(focused_id)
            ),
            None,
        )
        if row is None:
            return
        device_name = str(row.get("device_name", "") or "Radio").strip() or "Radio"
        observer_mode = str(row.get("device_class", "") or "").strip().lower() == "observer"
        state = str(row.get("assignment_state", "") or "").strip().lower()
        operating_name = str(row.get("operating_profile_name", "") or "Unassigned").strip() or "Unassigned"
        if state == "temporary_override":
            text = (
                f"{device_name} is running a temporary override with {operating_name}. "
                "Use Restore Default Model when the temporary assignment window ends."
            )
            level = "warning"
        elif row.get("operating_profile_id") in (None, "", 0):
            text = (
                (
                    f"{device_name} is currently unassigned. Assign the Receive-only SDR model to enable observer-safe "
                    "Messages, Map, background ingest, and Launch Control without transmit, QSY, or scheduler authority."
                )
                if observer_mode
                else f"{device_name} is currently unassigned. Assign an operating model if this radio should participate in Station Default workflows."
            )
            level = "warning"
        else:
            assignment_text = self._assignment_display_text(operating_name, state)
            if observer_mode:
                text = (
                    f"{device_name} is using {assignment_text}. This receive-only assignment does not grant transmit, "
                    "QSY, or scheduler authority. "
                    f"Endpoint summary: {str(row.get('endpoint_summary', '') or '--')}."
                )
            else:
                text = (
                    f"{device_name} is using {assignment_text}. "
                    f"Endpoint summary: {str(row.get('endpoint_summary', '') or '--')}."
                )
            level = "success" if int(row.get("runtime_primary", 0) or 0) == 1 else "info"
        self._set_guidance_card_state(
            self.device_assignments_guidance_card,
            self.device_assignments_guidance_title_label,
            self.device_assignments_guidance_status_label,
            title=f"{device_name} Operating Model Guidance",
            text=text,
            level=level,
        )

    def _current_varac_cluster_focus_id(self) -> int | None:
        if not hasattr(self, "varac_clusters_table"):
            return None
        item = self.varac_clusters_table.currentItem()
        if item is not None:
            row_item = self.varac_clusters_table.item(item.row(), 1)
            if row_item is not None:
                try:
                    ident = int(row_item.data(Qt.UserRole) or 0)
                except Exception:
                    ident = 0
                if ident > 0:
                    return ident
        first = next(
            (
                int(row.get("id", 0) or 0)
                for row in self.varac_clusters
                if isinstance(row, dict) and int(row.get("id", 0) or 0) > 0
            ),
            0,
        )
        return first or None

    def _update_varac_cluster_guidance_detail(self) -> None:
        if not hasattr(self, "varac_clusters_guidance_card"):
            return
        if not self._varac_cluster_mode_enabled():
            self._set_guidance_card_state(
                self.varac_clusters_guidance_card,
                self.varac_clusters_guidance_title_label,
                self.varac_clusters_guidance_status_label,
                title="Focused VarAC Cluster Guidance",
                text=(
                    "Cluster mode is off. Enable Cluster Mode in VarAC Settings only when multiple radio/profile-owned "
                    "VarAC instances should share coordinated cluster routing, BBS, or gateway behavior."
                ),
                level="info",
            )
            return
        focused_id = self._current_varac_cluster_focus_id()
        if not focused_id:
            self._set_guidance_card_state(
                self.varac_clusters_guidance_card,
                self.varac_clusters_guidance_title_label,
                self.varac_clusters_guidance_status_label,
                title="Focused VarAC Cluster Guidance",
                text=(
                    "Create a VarAC cluster to define the shared identity, optional shared DB path, refresh cadence, "
                    "and gateway handler for VarAC instances that are intentionally working together."
                ),
                level="info",
            )
            return
        cluster = self._varac_cluster_by_id(int(focused_id))
        if not cluster:
            return
        name = str(cluster.get("name", "") or "VarAC Cluster").strip() or "VarAC Cluster"
        enabled_members = int(cluster.get("enabled_member_count", 0) or 0)
        total_members = int(cluster.get("member_count", 0) or 0)
        gateway = str(cluster.get("gateway_handler_name", "") or "").strip()
        if enabled_members > 1 and not gateway:
            text = (
                f"{name} has {enabled_members} enabled members and should designate one gateway handler before operators rely on it for coordinated VarAC routing."
            )
            level = "warning"
        elif total_members <= 0:
            text = (
                f"{name} has no memberships yet. Add radios in VarAC Memberships, then return here to choose a gateway handler if the cluster will route through one device."
            )
            level = "info"
        else:
            text = (
                f"{name} currently has {enabled_members}/{total_members} enabled memberships. "
                f"Gateway handler: {gateway or 'not selected'}. Shared DB: {str(cluster.get('shared_db_path', '') or 'device-local only')}."
            )
            level = "success" if gateway or enabled_members <= 1 else "info"
        self._set_guidance_card_state(
            self.varac_clusters_guidance_card,
            self.varac_clusters_guidance_title_label,
            self.varac_clusters_guidance_status_label,
            title=f"{name} Guidance",
            text=text,
            level=level,
        )

    def _current_varac_membership_focus(self) -> Optional[Dict[str, Any]]:
        if not hasattr(self, "varac_members_table"):
            return next((dict(row) for row in self.varac_cluster_members if isinstance(row, dict)), None)
        current_row = self.varac_members_table.currentRow()
        if current_row >= 0 and current_row < len(self.varac_cluster_members):
            row = self.varac_cluster_members[current_row]
            if isinstance(row, dict):
                return dict(row)
        return next((dict(row) for row in self.varac_cluster_members if isinstance(row, dict)), None)

    def _device_has_varac_local_config(self, device_profile_id: int) -> bool:
        device = self._device_profile_by_id(int(device_profile_id))
        if not isinstance(device, dict):
            return False
        return any(
            str(device.get(key, "") or "").strip()
            for key in ("varac_install_path", "varac_db_path", "varac_ini_path", "launch_cmd")
        )

    def _update_varac_membership_guidance_detail(self) -> None:
        if not hasattr(self, "varac_memberships_guidance_card"):
            return
        if not self._varac_cluster_mode_enabled():
            self._set_guidance_card_state(
                self.varac_memberships_guidance_card,
                self.varac_memberships_guidance_title_label,
                self.varac_memberships_guidance_status_label,
                title="Focused VarAC Membership Guidance",
                text="Cluster mode is off. Enable Cluster Mode in VarAC Settings before assigning radios to coordinated VarAC memberships.",
                level="info",
            )
            return
        membership = self._current_varac_membership_focus()
        if not membership:
            self._set_guidance_card_state(
                self.varac_memberships_guidance_card,
                self.varac_memberships_guidance_title_label,
                self.varac_memberships_guidance_status_label,
                title="Focused VarAC Membership Guidance",
                text="Assign radios to a VarAC cluster when they should share cluster identity and coordinated routing behavior.",
                level="info",
            )
            return
        cluster_name = str(membership.get("cluster_name", "") or "Cluster").strip() or "Cluster"
        device_name = str(membership.get("device_name", "") or "Radio").strip() or "Radio"
        instance_number = int(membership.get("instance_number", 0) or 0)
        enabled = int(membership.get("enabled", 1) or 0) == 1
        is_gateway = bool(membership.get("is_gateway_handler"))
        node_ready = self._device_has_varac_local_config(int(membership.get("device_profile_id", 0) or 0))
        if enabled and not node_ready:
            text = (
                f"{device_name} is enabled in {cluster_name}, but the radio does not yet have enough device-local VarAC setup to participate confidently. "
                "Review that radio's VarAC paths in Radio Profiles."
            )
            level = "warning"
        else:
            role = "gateway handler" if is_gateway else "member"
            text = (
                f"{device_name} is configured as {role} in {cluster_name} on instance {instance_number}. "
                f"Membership is {'enabled' if enabled else 'disabled'}."
            )
            level = "success" if enabled else "info"
        self._set_guidance_card_state(
            self.varac_memberships_guidance_card,
            self.varac_memberships_guidance_title_label,
            self.varac_memberships_guidance_status_label,
            title=f"{device_name} Membership Guidance",
            text=text,
            level=level,
        )

    def _update_device_profile_action_buttons(self) -> None:
        if not hasattr(self, "add_device_profile_btn"):
            return
        theme = resolve_theme(self.settings)
        selected = self._selected_device_profiles()
        count = len(selected)
        selected_assignment_rows = self._selected_device_profiles_as_assignment_rows()
        observer_selected = bool(
            count == 1
            and str(selected[0].get("device_class", "") or "").strip().lower() == "observer"
        )
        has_enabled_profile = any(
            isinstance(row, dict) and int(row.get("enabled", 1) or 0) == 1 for row in self.operating_profiles
        )
        can_edit = count == 1
        can_activate = count > 0 and any(int(row.get("runtime_active", 0) or 0) != 1 for row in selected)
        can_deactivate = count > 0 and all(int(row.get("runtime_primary", 0) or 0) != 1 for row in selected) and any(
            int(row.get("runtime_active", 0) or 0) == 1 for row in selected
        )
        can_set_active = (
            count == 1
            and int(selected[0].get("runtime_primary", 0) or 0) != 1
            and str(selected[0].get("device_class", "") or "").strip().lower() != "observer"
        )
        can_delete = count > 0 and all(int(row.get("runtime_active", 0) or 0) != 1 for row in selected)
        can_assign_schedule = count > 0 and has_enabled_profile
        can_restore_schedule = count > 0 and any(
            str(row.get("assignment_state", "") or "").strip().lower() == "temporary_override"
            or str(row.get("operating_system_key", "") or "").strip() != "default_operating"
            for row in selected_assignment_rows
        )
        if hasattr(self, "selector_selected_device_profile_label"):
            if count == 1:
                selected_radio_text = self._profile_display_name(selected[0])
            elif count > 1:
                selected_radio_text = f"{count} radios"
            else:
                selected_radio_text = "--"
            self.selector_selected_device_profile_label.setText(selected_radio_text)
            self.selector_selected_device_profile_label.setAccessibleName(f"Selected radio: {selected_radio_text}")

        self.add_device_profile_btn.setStyleSheet(button_style("primary", theme))
        if hasattr(self, "copy_readiness_summary_btn"):
            self.copy_readiness_summary_btn.setStyleSheet(button_style("secondary", theme))
        self.edit_device_profile_btn.setEnabled(can_edit)
        self.edit_device_profile_btn.setStyleSheet(button_style("info" if can_edit else "muted", theme))
        if hasattr(self, "selector_edit_apps_btn"):
            self.selector_edit_apps_btn.setEnabled(can_edit)
            self.selector_edit_apps_btn.setText("Receiver Setup…" if observer_selected else "Change Software…")
            self.selector_edit_apps_btn.setToolTip(
                "Review the receiver endpoint, test reversible tuning, and enable CommsPlan tuning."
                if observer_selected
                else "Add or remove software used by the selected radio."
            )
            self.selector_edit_apps_btn.setAccessibleName(
                "Open selected receiver setup" if observer_selected else "Change selected radio software"
            )
            self.selector_edit_apps_btn.setStyleSheet(button_style("info" if can_edit else "muted", theme))
        if hasattr(self, "selector_software_details_btn"):
            self.selector_software_details_btn.setEnabled(can_edit)
            self.selector_software_details_btn.setVisible(not observer_selected)
            self.selector_software_details_btn.setStyleSheet(button_style("info" if can_edit else "muted", theme))
        if hasattr(self, "selector_manage_connections_btn"):
            self.selector_manage_connections_btn.setEnabled(can_edit)
            self.selector_manage_connections_btn.setStyleSheet(button_style("info" if can_edit else "muted", theme))
        if hasattr(self, "profile_edit_apps_btn"):
            self.profile_edit_apps_btn.setEnabled(can_edit)
            self.profile_edit_apps_btn.setVisible(count == 1)
            self.profile_edit_apps_btn.setText("Receiver Setup…" if observer_selected else "Change Software…")
            self.profile_edit_apps_btn.setToolTip(
                "Review the receiver endpoint, test reversible tuning, and enable CommsPlan tuning."
                if observer_selected
                else "Add or remove software used by the selected radio."
            )
            self.profile_edit_apps_btn.setAccessibleName(
                "Open selected receiver setup from profile"
                if observer_selected
                else "Change selected radio software from profile"
            )
            self.profile_edit_apps_btn.setStyleSheet(button_style("info" if can_edit else "muted", theme))
        if hasattr(self, "profile_software_details_btn"):
            self.profile_software_details_btn.setEnabled(can_edit)
            self.profile_software_details_btn.setVisible(count == 1 and not observer_selected)
            self.profile_software_details_btn.setStyleSheet(button_style("info" if can_edit else "muted", theme))
        if hasattr(self, "profile_manage_connections_btn"):
            self.profile_manage_connections_btn.setEnabled(can_edit)
            self.profile_manage_connections_btn.setVisible(count == 1)
            self.profile_manage_connections_btn.setStyleSheet(button_style("info" if can_edit else "muted", theme))
        self.activate_device_profile_btn.setEnabled(can_activate)
        self.activate_device_profile_btn.setStyleSheet(button_style("info" if can_activate else "muted", theme))
        if hasattr(self, "selector_activate_device_profile_btn"):
            self.selector_activate_device_profile_btn.setEnabled(can_activate)
            self.selector_activate_device_profile_btn.setStyleSheet(button_style("primary" if can_activate else "muted", theme))
        if hasattr(self, "profile_activate_device_profile_btn"):
            self.profile_activate_device_profile_btn.setEnabled(can_activate)
            self.profile_activate_device_profile_btn.setVisible(count == 1)
            self.profile_activate_device_profile_btn.setStyleSheet(button_style("primary" if can_activate else "muted", theme))
        self.deactivate_device_profile_btn.setEnabled(can_deactivate)
        self.deactivate_device_profile_btn.setStyleSheet(button_style("warning" if can_deactivate else "muted", theme))
        if hasattr(self, "selector_deactivate_device_profile_btn"):
            self.selector_deactivate_device_profile_btn.setEnabled(can_deactivate)
            self.selector_deactivate_device_profile_btn.setStyleSheet(button_style("warning" if can_deactivate else "muted", theme))
        if hasattr(self, "profile_deactivate_device_profile_btn"):
            self.profile_deactivate_device_profile_btn.setEnabled(can_deactivate)
            self.profile_deactivate_device_profile_btn.setVisible(count == 1)
            self.profile_deactivate_device_profile_btn.setStyleSheet(button_style("warning" if can_deactivate else "muted", theme))
        self.assign_radio_schedule_btn.setEnabled(can_assign_schedule)
        self.assign_radio_schedule_btn.setStyleSheet(button_style("info" if can_assign_schedule else "muted", theme))
        self.restore_radio_schedule_btn.setEnabled(can_restore_schedule)
        self.restore_radio_schedule_btn.setStyleSheet(button_style("warning" if can_restore_schedule else "muted", theme))
        self.set_active_device_profile_btn.setEnabled(can_set_active)
        self.set_active_device_profile_btn.setStyleSheet(button_style("info" if can_set_active else "muted", theme))
        if hasattr(self, "selector_set_default_device_profile_btn"):
            self.selector_set_default_device_profile_btn.setEnabled(can_set_active)
            self.selector_set_default_device_profile_btn.setStyleSheet(button_style("info" if can_set_active else "muted", theme))
        self.delete_device_profile_btn.setEnabled(can_delete)
        self.delete_device_profile_btn.setStyleSheet(button_style("warning" if can_delete else "muted", theme))
        if hasattr(self, "selector_remove_device_profile_btn"):
            self.selector_remove_device_profile_btn.setEnabled(can_delete)
            self.selector_remove_device_profile_btn.setStyleSheet(button_style("warning" if can_delete else "muted", theme))

    def _refresh_device_profiles_table(self, *, refresh_section_titles: bool = True) -> None:
        if not hasattr(self, "device_profiles_table"):
            return
        table = self.device_profiles_table
        try:
            self.device_profiles = list(self.multi_radio_store.list_device_profiles())
        except Exception:
            log.exception("Failed loading device profiles from store.")
            self.device_profiles = []
        effective_assignments = self._effective_assignment_map()
        operating_profiles_by_id = {
            int(row.get("id", 0) or 0): dict(row)
            for row in self.operating_profiles
            if isinstance(row, dict)
        }
        readiness_report = self._current_station_readiness_report()
        self._device_profiles_table_loading = True
        try:
            table.setRowCount(0)
            for profile in self.device_profiles:
                row = table.rowCount()
                table.insertRow(row)
                profile_id = int(profile.get("id", 0) or 0)

                sel_chk = QCheckBox()
                sel_chk.setFixedWidth(22)
                sel_chk.setProperty("device_profile_id", profile_id)
                sel_chk.stateChanged.connect(self._update_device_profile_action_buttons)
                sel_wrap = QWidget()
                sel_layout = QHBoxLayout(sel_wrap)
                sel_layout.setContentsMargins(0, 0, 0, 0)
                sel_layout.setAlignment(Qt.AlignCenter)
                sel_layout.addWidget(sel_chk)
                table.setCellWidget(row, 0, sel_wrap)

                active_item = QTableWidgetItem("Yes" if int(profile.get("runtime_active", 0) or 0) == 1 else "")
                active_item.setTextAlignment(Qt.AlignCenter)
                table.setItem(row, 1, active_item)

                primary_item = QTableWidgetItem("Yes" if int(profile.get("runtime_primary", 0) or 0) == 1 else "")
                primary_item.setTextAlignment(Qt.AlignCenter)
                table.setItem(row, 2, primary_item)

                name_item = QTableWidgetItem(str(profile.get("name", "") or ""))
                name_item.setData(Qt.UserRole, profile_id)
                table.setItem(row, 3, name_item)

                table.setItem(row, 4, QTableWidgetItem(self._device_radio_model_summary(profile)))

                backend = str(profile.get("control_backend", "") or "")
                backend_item = QTableWidgetItem(self._device_backend_label(backend))
                if backend.strip().lower() == "rigctld":
                    backend_item.setToolTip("Active RIGCTLD profiles use the configured TCP endpoint.")
                table.setItem(row, 5, backend_item)
                table.setItem(row, 6, QTableWidgetItem(self._device_deployment_label(str(profile.get("deployment_mode", "") or ""))))
                table.setItem(row, 7, QTableWidgetItem(self._device_software_summary(profile)))
                table.setItem(row, 8, QTableWidgetItem(self._device_endpoint_summary(profile)))
                assignment = effective_assignments.get(profile_id, {})
                assigned_profile = operating_profiles_by_id.get(int(assignment.get("operating_profile_id", 0) or 0), {})
                assigned_name = str((assigned_profile or assignment).get("operating_profile_name", "") or (assigned_profile or {}).get("name", "") or "Unassigned").strip() or "Unassigned"
                if assigned_name != "Unassigned":
                    assignment_state = str(assignment.get("assignment_state", "") or "").strip().lower()
                    assigned_name = self._assignment_display_text(assigned_name, assignment_state)
                table.setItem(row, 9, QTableWidgetItem(assigned_name))
                readiness_item = QTableWidgetItem(self._device_readiness_summary(profile, readiness_report))
                readiness_item.setTextAlignment(Qt.AlignCenter)
                radio_issues = [
                    issue
                    for issue in readiness_report.issues
                    if int(issue.radio_id or 0) == profile_id
                ]
                if radio_issues:
                    readiness_item.setToolTip(
                        "\n".join(
                            format_readiness_issue(issue)
                            for issue in radio_issues[:6]
                        )
                    )
                table.setItem(row, 10, readiness_item)
                table.setItem(row, 11, QTableWidgetItem("Opt-in" if self._radio_profile_launch_opt_in_enabled(profile) else "Off"))
                ptt_item = QTableWidgetItem(self._device_ptt_group_label(profile.get("ptt_group", "")))
                ptt_item.setTextAlignment(Qt.AlignCenter)
                table.setItem(row, 12, ptt_item)
                class_item = QTableWidgetItem(self._device_class_label(str(profile.get("device_class", "") or "")))
                class_item.setTextAlignment(Qt.AlignCenter)
                table.setItem(row, 13, class_item)
                table.setItem(row, 14, QTableWidgetItem(str(profile.get("notes", "") or "")))
        finally:
            self._device_profiles_table_loading = False
        self._fit_table_height_to_rows(table, min_rows=1, max_rows=8, extra_rows=1)
        self._ensure_settings_radio_focus_id()
        if table.rowCount() > 0:
            self._sync_device_profiles_table_to_settings_focus()
        self._rebuild_status_indicators()
        self._rebuild_device_profile_selector()
        self._update_device_profiles_hint()
        self._refresh_multi_rig_status_card()
        self._update_device_profile_action_buttons()
        self._update_device_profile_readiness_detail(readiness_report)
        self._refresh_radio_specific_section_visibility()
        self._refresh_launch_control_guidance()
        self._refresh_software_administration_snapshot()
        self._refresh_section_nav_health()
        if refresh_section_titles:
            self._refresh_section_titles()

    def _refresh_multi_radio_tables(self, *, refresh_section_titles: bool = True) -> None:
        # A guided save composes the radio, application rows, manifests,
        # canonical identities, launch rows, and optional cluster membership in
        # one SQLite transaction.  Reading that connection halfway through the
        # transaction used to expose the provisional radio in Settings while
        # Software Administration still held its pre-save snapshot.  Never
        # publish that mixed generation; the outer owner performs one reload
        # after commit or rollback.
        if getattr(self, "_guided_save_ui_deferred", False):
            return
        self._refresh_device_profiles_table(refresh_section_titles=refresh_section_titles)
        self._refresh_operating_profiles_table(
            refresh_assignments=True,
            refresh_section_titles=refresh_section_titles,
        )
        self._refresh_schedule_assignments_table(refresh_section_titles=refresh_section_titles)
        self._refresh_varac_clusters_table(
            refresh_memberships=True,
            refresh_section_titles=refresh_section_titles,
        )
        self._refresh_software_radio_selector(preserve_current=True)

    def _summary_varac_clusters(self) -> str:
        if not self._varac_cluster_mode_enabled():
            return "Cluster mode off"
        rows = [row for row in self.varac_clusters if isinstance(row, dict)]
        count = len(rows)
        members = sum(int(row.get("enabled_member_count", 0) or 0) for row in rows)
        gateway_count = len([row for row in rows if row.get("gateway_handler_device_id") not in (None, "", 0)])
        if count <= 0:
            return "No VarAC clusters"
        return (
            f"{count} cluster{'s' if count != 1 else ''}, "
            f"{members} member{'s' if members != 1 else ''}, "
            f"{gateway_count} gateway"
        )

    def _summary_varac_memberships(self) -> str:
        if not self._varac_cluster_mode_enabled():
            return "Cluster mode off"
        rows = [row for row in self.varac_cluster_members if isinstance(row, dict)]
        if not rows:
            return "No VarAC memberships"
        enabled_count = len([row for row in rows if int(row.get("enabled", 1) or 0) == 1])
        gateway_count = len([row for row in rows if bool(row.get("is_gateway_handler"))])
        return f"{enabled_count}/{len(rows)} enabled, {gateway_count} gateway handler{'s' if gateway_count != 1 else ''}"

    def _update_varac_clusters_hint(self) -> None:
        label = getattr(self, "varac_clusters_hint_label", None)
        if label is None:
            return
        if not self._varac_cluster_mode_enabled():
            label.setText(
                "Cluster mode is off. Enable Cluster Mode in VarAC Settings only when multiple VarAC instances should share coordinated routing, BBS, or gateway behavior."
            )
            return
        if not self.varac_clusters:
            label.setText(
                "Define shared VarAC clusters here. A cluster holds the shared identity, optional shared DB path, "
                "refresh cadence, and designated gateway handler for enabled members. Keep separate VarAC instances on distinct paths, ports, and folders unless sharing is intentional."
            )
            return
        missing_gateway = [
            row
            for row in self.varac_clusters
            if isinstance(row, dict)
            and int(row.get("enabled_member_count", 0) or 0) > 1
            and row.get("gateway_handler_device_id") in (None, "", 0)
        ]
        if missing_gateway:
            names = ", ".join(str(row.get("name", "") or "Cluster").strip() for row in missing_gateway[:3])
            label.setText(
                f"Clusters with more than one enabled member should select one gateway handler. Pending handler selection: {names}."
            )
            return
        label.setText(
            "Define shared VarAC clusters here. Edit a cluster to choose its gateway handler from the enabled "
            "members already assigned to that cluster. Avoid sharing live BBS folders unless the cluster is intentionally operating from a common store."
        )

    def _update_varac_memberships_hint(self) -> None:
        label = getattr(self, "varac_members_hint_label", None)
        if label is None:
            return
        if not self._varac_cluster_mode_enabled():
            label.setText(
                "Cluster mode is off. Enable Cluster Mode in VarAC Settings before assigning radios to VarAC clusters."
            )
            return
        if not self.varac_cluster_members:
            label.setText(
                "Assign device profiles to VarAC clusters here. Each membership should make clear which CommsPlan radio/profile owns the VarAC instance. "
                "Use distinct instance numbers and device-local paths for separate running instances."
            )
            return
        missing_node_config = [
            row
            for row in self.varac_cluster_members
            if isinstance(row, dict)
            and int(row.get("enabled", 1) or 0) == 1
            and not any(
                str(device.get(key, "") or "").strip()
                for device in self.device_profiles
                if isinstance(device, dict) and int(device.get("id", 0) or 0) == int(row.get("device_profile_id", 0) or 0)
                for key in ("varac_install_path", "varac_db_path", "varac_ini_path", "launch_cmd")
            )
        ]
        if missing_node_config:
            names = ", ".join(str(row.get("device_name", "") or "Device").strip() for row in missing_node_config[:3])
            label.setText(
                f"Enabled cluster memberships should also have device-local VarAC settings. Review: {names}."
            )
            return
        label.setText(
            "Assign device profiles to VarAC clusters here. Instance numbers must be unique within each cluster, "
            "and the gateway handler must be one of that cluster's enabled members. Shared BBS folders should be deliberate, not accidental."
        )

    def _selected_varac_cluster_ids(self) -> List[int]:
        rows: List[int] = []
        if not hasattr(self, "varac_clusters_table"):
            return rows
        for row in range(self.varac_clusters_table.rowCount()):
            wrapper = self.varac_clusters_table.cellWidget(row, 0)
            chk = wrapper.findChild(QCheckBox) if wrapper is not None else None
            if chk is None or not chk.isChecked():
                continue
            try:
                rows.append(int(chk.property("varac_cluster_id")))
            except Exception:
                continue
        return rows

    def _selected_varac_clusters(self) -> List[Dict[str, Any]]:
        selected_ids = set(self._selected_varac_cluster_ids())
        return [
            dict(row)
            for row in self.varac_clusters
            if isinstance(row, dict) and int(row.get("id", 0) or 0) in selected_ids
        ]

    def _selected_varac_memberships(self) -> List[Dict[str, Any]]:
        selected_pairs: set[tuple[int, int]] = set()
        if not hasattr(self, "varac_members_table"):
            return []
        for row in range(self.varac_members_table.rowCount()):
            wrapper = self.varac_members_table.cellWidget(row, 0)
            chk = wrapper.findChild(QCheckBox) if wrapper is not None else None
            if chk is None or not chk.isChecked():
                continue
            try:
                selected_pairs.add(
                    (
                        int(chk.property("varac_cluster_id") or 0),
                        int(chk.property("device_profile_id") or 0),
                    )
                )
            except Exception:
                continue
        return [
            dict(row)
            for row in self.varac_cluster_members
            if isinstance(row, dict)
            and (
                int(row.get("cluster_db_id", 0) or 0),
                int(row.get("device_profile_id", 0) or 0),
            )
            in selected_pairs
        ]

    def _update_varac_cluster_action_buttons(self) -> None:
        if not hasattr(self, "add_varac_cluster_btn"):
            return
        theme = resolve_theme(self.settings)
        selected = self._selected_varac_clusters()
        count = len(selected)
        can_edit = count == 1
        can_delete = count > 0
        self.add_varac_cluster_btn.setStyleSheet(button_style("primary", theme))
        self.edit_varac_cluster_btn.setEnabled(can_edit)
        self.edit_varac_cluster_btn.setStyleSheet(button_style("info" if can_edit else "muted", theme))
        self.delete_varac_cluster_btn.setEnabled(can_delete)
        self.delete_varac_cluster_btn.setStyleSheet(button_style("warning" if can_delete else "muted", theme))

    def _update_varac_membership_action_buttons(self) -> None:
        if not hasattr(self, "add_varac_membership_btn"):
            return
        theme = resolve_theme(self.settings)
        selected = self._selected_varac_memberships()
        can_remove = len(selected) > 0
        self.add_varac_membership_btn.setStyleSheet(button_style("primary", theme))
        self.remove_varac_membership_btn.setEnabled(can_remove)
        self.remove_varac_membership_btn.setStyleSheet(button_style("warning" if can_remove else "muted", theme))

    def _refresh_varac_clusters_table(
        self,
        *,
        refresh_memberships: bool = True,
        refresh_section_titles: bool = True,
    ) -> None:
        if not hasattr(self, "varac_clusters_table"):
            return
        table = self.varac_clusters_table
        try:
            self.varac_clusters = list(self.multi_radio_store.list_varac_clusters())
        except Exception:
            log.exception("Failed loading VarAC clusters from store.")
            self.varac_clusters = []
        mode_changed = self._sync_varac_cluster_mode_from_saved_topology()
        if not self._varac_cluster_mode_enabled():
            self.varac_cluster_members = []
            self.varac_clusters_table.setRowCount(0)
            if hasattr(self, "varac_members_table"):
                self.varac_members_table.setRowCount(0)
            self._update_varac_clusters_hint()
            self._update_varac_memberships_hint()
            self._update_varac_cluster_action_buttons()
            self._update_varac_cluster_guidance_detail()
            self._update_varac_membership_guidance_detail()
            if refresh_section_titles:
                self._refresh_section_titles()
            return
        if mode_changed:
            self._refresh_varac_cluster_mode_ui(refresh_tables=False)
        self._varac_clusters_table_loading = True
        try:
            table.setRowCount(0)
            for cluster in self.varac_clusters:
                row = table.rowCount()
                table.insertRow(row)
                cluster_id = int(cluster.get("id", 0) or 0)
                sel_chk = QCheckBox()
                sel_chk.setFixedWidth(22)
                sel_chk.setProperty("varac_cluster_id", cluster_id)
                sel_chk.stateChanged.connect(self._update_varac_cluster_action_buttons)
                sel_wrap = QWidget()
                sel_layout = QHBoxLayout(sel_wrap)
                sel_layout.setContentsMargins(0, 0, 0, 0)
                sel_layout.setAlignment(Qt.AlignCenter)
                sel_layout.addWidget(sel_chk)
                table.setCellWidget(row, 0, sel_wrap)
                name_item = QTableWidgetItem(str(cluster.get("name", "") or ""))
                name_item.setData(Qt.UserRole, cluster_id)
                table.setItem(row, 1, name_item)
                table.setItem(row, 2, QTableWidgetItem(str(cluster.get("cluster_id", "") or "")))
                table.setItem(row, 3, QTableWidgetItem(str(cluster.get("shared_db_path", "") or "")))
                table.setItem(
                    row,
                    4,
                    QTableWidgetItem(f"{int(cluster.get('enabled_member_count', 0) or 0)}/{int(cluster.get('member_count', 0) or 0)}"),
                )
                table.setItem(row, 5, QTableWidgetItem(str(cluster.get("gateway_handler_name", "") or "")))
                table.setItem(row, 6, QTableWidgetItem("On" if int(cluster.get("ptt_lock_enabled", 0) or 0) == 1 else "Off"))
                table.setItem(row, 7, QTableWidgetItem(f"{int(cluster.get('counters_refresh_sec', 30) or 30)}s"))
        finally:
            self._varac_clusters_table_loading = False
        if table.rowCount() > 0 and table.currentRow() < 0:
            table.selectRow(0)
        self._update_varac_clusters_hint()
        self._update_varac_cluster_action_buttons()
        self._update_varac_cluster_guidance_detail()
        if refresh_memberships and hasattr(self, "varac_members_table"):
            self._refresh_varac_memberships_table(refresh_section_titles=False)
        if refresh_section_titles:
            self._refresh_section_titles()

    def _refresh_varac_memberships_table(self, *, refresh_section_titles: bool = True) -> None:
        if not hasattr(self, "varac_members_table"):
            return
        if not self._varac_cluster_mode_enabled():
            self.varac_cluster_members = []
            self.varac_members_table.setRowCount(0)
            self._update_varac_memberships_hint()
            self._update_varac_membership_action_buttons()
            self._update_varac_membership_guidance_detail()
            if refresh_section_titles:
                self._refresh_section_titles()
            return
        table = self.varac_members_table
        try:
            self.varac_cluster_members = list(self.multi_radio_store.list_varac_cluster_members())
        except Exception:
            log.exception("Failed loading VarAC cluster memberships from store.")
            self.varac_cluster_members = []
        self._varac_cluster_members_table_loading = True
        try:
            table.setRowCount(0)
            for membership in self.varac_cluster_members:
                row = table.rowCount()
                table.insertRow(row)
                cluster_id = int(membership.get("cluster_db_id", 0) or 0)
                device_id = int(membership.get("device_profile_id", 0) or 0)
                sel_chk = QCheckBox()
                sel_chk.setFixedWidth(22)
                sel_chk.setProperty("varac_cluster_id", cluster_id)
                sel_chk.setProperty("device_profile_id", device_id)
                sel_chk.stateChanged.connect(self._update_varac_membership_action_buttons)
                sel_wrap = QWidget()
                sel_layout = QHBoxLayout(sel_wrap)
                sel_layout.setContentsMargins(0, 0, 0, 0)
                sel_layout.setAlignment(Qt.AlignCenter)
                sel_layout.addWidget(sel_chk)
                table.setCellWidget(row, 0, sel_wrap)
                table.setItem(row, 1, QTableWidgetItem(str(membership.get("cluster_name", "") or "")))
                table.setItem(row, 2, QTableWidgetItem(str(membership.get("device_name", "") or "")))
                runtime_label = "Primary" if int(membership.get("runtime_primary", 0) or 0) == 1 else ("Active" if int(membership.get("runtime_active", 0) or 0) == 1 else "")
                runtime_item = QTableWidgetItem(runtime_label)
                runtime_item.setTextAlignment(Qt.AlignCenter)
                table.setItem(row, 3, runtime_item)
                table.setItem(row, 4, QTableWidgetItem(self._device_class_label(str(membership.get("device_class", "") or ""))))
                instance_item = QTableWidgetItem(str(int(membership.get("instance_number", 0) or 0)))
                instance_item.setTextAlignment(Qt.AlignCenter)
                table.setItem(row, 5, instance_item)
                enabled_item = QTableWidgetItem("Yes" if int(membership.get("enabled", 1) or 0) == 1 else "")
                enabled_item.setTextAlignment(Qt.AlignCenter)
                table.setItem(row, 6, enabled_item)
                table.setItem(row, 7, QTableWidgetItem("Handler" if bool(membership.get("is_gateway_handler")) else "Member"))
        finally:
            self._varac_cluster_members_table_loading = False
        if table.rowCount() > 0 and table.currentRow() < 0:
            table.selectRow(0)
        self._update_varac_memberships_hint()
        self._update_varac_membership_action_buttons()
        self._update_varac_clusters_hint()
        self._update_varac_membership_guidance_detail()
        if refresh_section_titles:
            self._refresh_section_titles()

    # ---------- Operating Models / Operating Model Assignment ---------- #

    def _summary_operating_profiles(self) -> str:
        count = len(self.operating_profiles)
        enabled_count = len(
            [row for row in self.operating_profiles if isinstance(row, dict) and int(row.get("enabled", 1) or 0) == 1]
        )
        if count <= 0:
            return "No operating models"
        return f"{count} operating model{'s' if count != 1 else ''}, {enabled_count} enabled"

    def _summary_device_assignments(self) -> str:
        rows = [row for row in self.device_assignments if isinstance(row, dict)]
        if not rows:
            return "No assigned models"
        overrides = len(
            [row for row in rows if str(row.get("assignment_state", "") or "").strip().lower() == "temporary_override"]
        )
        assigned = len([row for row in rows if row.get("operating_profile_id") not in (None, "", 0)])
        summary = f"{assigned} assigned"
        if overrides:
            summary += f", {overrides} temporary override{'s' if overrides != 1 else ''}"
        if isinstance(self.active_profile_swap, dict) and self.active_profile_swap:
            summary += ", swap active"
        return summary

    def _summary_schedule_assignments(self) -> str:
        rows = [row for row in getattr(self, "schedule_assignments", []) if isinstance(row, dict)]
        if not rows:
            return "No schedule assignments"
        assigned = len([row for row in rows if row.get("frequency_plan_id") not in (None, "", 0)])
        needs_guard = len(
            [
                row
                for row in rows
                if str(row.get("guard_status", "") or "").strip().lower() in {"not enforced", "needs review"}
            ]
        )
        summary = f"{assigned} assigned"
        if needs_guard:
            summary += f", {needs_guard} guard review"
        return summary

    def _operating_profile_by_id(self, operating_profile_id: int) -> Optional[Dict[str, Any]]:
        for row in self.operating_profiles:
            if not isinstance(row, dict):
                continue
            if int(row.get("id", 0) or 0) == int(operating_profile_id):
                return dict(row)
        return None

    @staticmethod
    def _assignment_state_label(state: str) -> str:
        normalized = str(state or "").strip().lower()
        labels = {
            "active": "Active",
            "inactive": "Inactive",
            "scheduled": "Scheduled",
            "superseded": "Superseded",
            "temporary_override": "Temporary Override",
            "unassigned": "Unassigned",
        }
        if normalized in labels:
            return labels[normalized]
        return normalized.replace("_", " ").title() if normalized else "Unassigned"

    @staticmethod
    def _assignment_display_text(name: object, state: object = "") -> str:
        assignment_name = str(name or "").strip() or "Unassigned"
        if assignment_name.lower() == "unassigned":
            return "Unassigned"
        return f"{assignment_name} ({SettingsTab._assignment_state_label(str(state or ''))})"

    @staticmethod
    def _scheduler_mode_label(raw: object) -> str:
        value = str(raw or "full").strip().lower() or "full"
        for label, option_value in OPERATING_SCHEDULER_MODE_OPTIONS:
            if option_value == value:
                return label
        return value.replace("_", " ").title()

    @staticmethod
    def _operating_profile_shell_summary(profile: Optional[Dict[str, Any]]) -> str:
        if not isinstance(profile, dict):
            return "Unassigned"
        bits: List[str] = []
        if int(profile.get("receive_only", 0) or 0) == 1:
            bits.append("Receive-only")
        if int(profile.get("scheduler_enabled", 1) or 0) != 1:
            bits.append("Scheduler Off")
        if int(profile.get("use_messages", 1) or 0) != 1:
            bits.append("Messages Off")
        if int(profile.get("use_map", 1) or 0) != 1:
            bits.append("Map Off")
        if int(profile.get("use_background_ingest", 1) or 0) != 1:
            bits.append("Ingest Off")
        if int(profile.get("use_launch_control", 0) or 0) != 1:
            bits.append("Launch Off")
        if int(profile.get("use_net_control_tabs", 1) or 0) != 1:
            bits.append("NetCtrl Off")
        if not bits:
            return "All CommsPlan features"
        return ", ".join(bits)

    def _selected_operating_profile_ids(self) -> List[int]:
        if not hasattr(self, "operating_profiles_table"):
            return []
        selected: List[int] = []
        for row in range(self.operating_profiles_table.rowCount()):
            wrapper = self.operating_profiles_table.cellWidget(row, 0)
            chk = wrapper.findChild(QCheckBox) if wrapper is not None else None
            if chk is None or not chk.isChecked():
                continue
            try:
                selected.append(int(chk.property("operating_profile_id") or 0))
            except Exception:
                continue
        return selected

    def _selected_operating_profiles(self) -> List[Dict[str, Any]]:
        selected_ids = set(self._selected_operating_profile_ids())
        return [
            dict(row)
            for row in self.operating_profiles
            if isinstance(row, dict) and int(row.get("id", 0) or 0) in selected_ids
        ]

    def _selected_assignment_rows(self) -> List[Dict[str, Any]]:
        if not hasattr(self, "device_assignments_table"):
            return []
        selected: List[Dict[str, Any]] = []
        for row in range(self.device_assignments_table.rowCount()):
            wrapper = self.device_assignments_table.cellWidget(row, 0)
            chk = wrapper.findChild(QCheckBox) if wrapper is not None else None
            if chk is None or not chk.isChecked():
                continue
            try:
                device_profile_id = int(chk.property("device_profile_id") or 0)
            except Exception:
                continue
            match = next(
                (
                    dict(item)
                    for item in self.device_assignments
                    if isinstance(item, dict) and int(item.get("device_profile_id", 0) or 0) == device_profile_id
                ),
                None,
            )
            if match is not None:
                selected.append(match)
        return selected

    def _update_operating_profiles_hint(self) -> None:
        if not hasattr(self, "operating_profiles_hint_label"):
            return
        if not self.operating_profiles:
            self.operating_profiles_hint_label.setText("No operating models are available.")
            return
        primary_assignment = next(
            (
                row
                for row in self.device_assignments
                if isinstance(row, dict) and int(row.get("runtime_primary", 0) or 0) == 1
            ),
            None,
        )
        hint = (
            "Operating models define which CommsPlan features and scheduler behavior apply when a built Frequency Plan "
            "or schedule is assigned to a radio. They are assigned separately from schedules."
        )
        if isinstance(primary_assignment, dict):
            operating_name = str(primary_assignment.get("operating_profile_name", "") or "").strip() or DEFAULT_OPERATING_NAME
            state_label = self._assignment_state_label(str(primary_assignment.get("assignment_state", "") or "active"))
            hint = f"Station default operating model: {operating_name} ({state_label}). " + hint
        self.operating_profiles_hint_label.setText(hint)

    def _update_device_assignments_hint(self) -> None:
        if not hasattr(self, "device_assignments_hint_label"):
            return
        active_swap = dict(self.active_profile_swap or {})
        if active_swap:
            source_name = str(active_swap.get("source_device_name", "") or "").strip() or "previous primary"
            target_name = str(active_swap.get("target_device_name", "") or "").strip() or "target radio"
            mode = str(active_swap.get("mode", "") or "").strip().lower()
            if mode == "carry_primary_profile":
                carried_name = (
                    str(active_swap.get("applied_operating_profile_name", "") or "").strip()
                    or "the previous primary operating model"
                )
                self.device_assignments_hint_label.setText(
                    f"Temporary model swap active: {source_name} -> {target_name}. "
                    f"{carried_name} is temporarily applied on the target radio. Restore Swap returns the previous primary and target model assignment."
                )
            else:
                self.device_assignments_hint_label.setText(
                    f"Temporary model swap active: {source_name} -> {target_name}. "
                    "Restore Swap returns the previous primary radio without rewriting endpoint settings."
                )
            return
        rows = [row for row in self.device_assignments if isinstance(row, dict)]
        if not rows:
            self.device_assignments_hint_label.setText("No assigned operating models are available.")
            return
        assigned = len([row for row in rows if row.get("operating_profile_id") not in (None, "", 0)])
        overrides = len(
            [row for row in rows if str(row.get("assignment_state", "") or "").strip().lower() == "temporary_override"]
        )
        primary = next((row for row in rows if int(row.get("runtime_primary", 0) or 0) == 1), None)
        hint = f"{assigned} radio{'s' if assigned != 1 else ''} currently have an effective assigned operating model."
        if overrides:
            hint += f" {overrides} temporary override{'s are' if overrides != 1 else ' is'} active."
        if isinstance(primary, dict):
            operating_name = str(primary.get("operating_profile_name", "") or "").strip() or DEFAULT_OPERATING_NAME
            hint += f" The Station Default radio is currently using {operating_name}."
        self.device_assignments_hint_label.setText(hint)

    def _update_operating_profile_action_buttons(self) -> None:
        if not hasattr(self, "add_operating_profile_btn"):
            return
        theme = resolve_theme(self.settings)
        selected = self._selected_operating_profiles()
        count = len(selected)
        assigned_ids = {
            int(row.get("operating_profile_id", 0) or 0)
            for row in self.device_assignments
            if isinstance(row, dict) and row.get("operating_profile_id") not in (None, "", 0)
        }
        can_edit = count == 1
        can_delete = count > 0 and all(
            str(row.get("system_key", "") or "").strip() != "default_operating"
            and int(row.get("id", 0) or 0) not in assigned_ids
            for row in selected
        )
        self.add_operating_profile_btn.setStyleSheet(button_style("primary", theme))
        self.edit_operating_profile_btn.setEnabled(can_edit)
        self.edit_operating_profile_btn.setStyleSheet(button_style("info" if can_edit else "muted", theme))
        self.delete_operating_profile_btn.setEnabled(can_delete)
        self.delete_operating_profile_btn.setStyleSheet(button_style("warning" if can_delete else "muted", theme))

    def _update_device_assignment_action_buttons(self) -> None:
        if not hasattr(self, "assign_device_operating_profile_btn"):
            return
        theme = resolve_theme(self.settings)
        selected = self._selected_assignment_rows()
        count = len(selected)
        active_swap = dict(self.active_profile_swap or {})
        swap_device_ids = {
            int(active_swap.get("source_device_id", 0) or 0),
            int(active_swap.get("target_device_id", 0) or 0),
        }
        swap_device_ids.discard(0)
        selection_includes_swap_devices = any(
            int(row.get("device_profile_id", 0) or 0) in swap_device_ids for row in selected
        )
        compatible_profiles = self._assignment_profiles_for_devices(self.operating_profiles, selected)
        has_compatible_profile = bool(compatible_profiles)
        can_assign = count > 0 and has_compatible_profile and not selection_includes_swap_devices
        can_restore = count > 0 and not selection_includes_swap_devices and any(
            str(row.get("assignment_state", "") or "").strip().lower() == "temporary_override"
            or str(row.get("operating_system_key", "") or "").strip() != "default_operating"
            for row in selected
        )
        can_swap = (
            not active_swap
            and count == 1
            and int(selected[0].get("runtime_active", 0) or 0) == 1
            and int(selected[0].get("runtime_primary", 0) or 0) != 1
            and str(selected[0].get("device_class", "") or "").strip().lower() != "observer"
        )
        can_restore_swap = bool(active_swap)
        self.assign_device_operating_profile_btn.setEnabled(can_assign)
        observer_selected = any(
            str(row.get("device_class", "") or "").strip().lower() == "observer"
            for row in selected
        )
        if observer_selected and count > 0 and not has_compatible_profile:
            self.assign_device_operating_profile_btn.setToolTip(
                "No enabled receive-only Operating Model is available. Restore or create one before assigning this SDR."
            )
        elif observer_selected:
            self.assign_device_operating_profile_btn.setToolTip(
                "Assign an enabled receive-only Operating Model to the selected observer / SDR."
            )
        else:
            self.assign_device_operating_profile_btn.setToolTip("Assign an enabled Operating Model to the selected radio.")
        self.assign_device_operating_profile_btn.setStyleSheet(button_style("info" if can_assign else "muted", theme))
        self.temporary_profile_swap_btn.setEnabled(can_swap)
        self.temporary_profile_swap_btn.setStyleSheet(button_style("info" if can_swap else "muted", theme))
        self.restore_profile_swap_btn.setEnabled(can_restore_swap)
        self.restore_profile_swap_btn.setStyleSheet(button_style("warning" if can_restore_swap else "muted", theme))
        self.restore_device_operating_profile_btn.setEnabled(can_restore)
        self.restore_device_operating_profile_btn.setStyleSheet(button_style("warning" if can_restore else "muted", theme))
        if hasattr(self, "assignment_editor_save_btn"):
            self.assignment_editor_save_btn.setStyleSheet(button_style("primary", theme))
        if hasattr(self, "assignment_editor_cancel_btn"):
            self.assignment_editor_cancel_btn.setStyleSheet(button_style("secondary", theme))

    def _refresh_operating_profiles_table(
        self,
        *,
        refresh_assignments: bool = True,
        refresh_section_titles: bool = True,
    ) -> None:
        if not hasattr(self, "operating_profiles_table"):
            return
        table = self.operating_profiles_table
        try:
            self.operating_profiles = list(self.multi_radio_store.list_operating_profiles())
        except Exception:
            log.exception("Failed loading operating models from store.")
            self.operating_profiles = []
        self._operating_profiles_table_loading = True
        try:
            table.setRowCount(0)
            for profile in self.operating_profiles:
                row = table.rowCount()
                table.insertRow(row)
                profile_id = int(profile.get("id", 0) or 0)

                sel_chk = QCheckBox()
                sel_chk.setFixedWidth(22)
                sel_chk.setProperty("operating_profile_id", profile_id)
                sel_chk.stateChanged.connect(self._update_operating_profile_action_buttons)
                sel_wrap = QWidget()
                sel_layout = QHBoxLayout(sel_wrap)
                sel_layout.setContentsMargins(0, 0, 0, 0)
                sel_layout.setAlignment(Qt.AlignCenter)
                sel_layout.addWidget(sel_chk)
                table.setCellWidget(row, 0, sel_wrap)

                enabled_item = QTableWidgetItem("Yes" if int(profile.get("enabled", 1) or 0) == 1 else "")
                enabled_item.setTextAlignment(Qt.AlignCenter)
                table.setItem(row, 1, enabled_item)

                name_item = QTableWidgetItem(str(profile.get("name", "") or ""))
                name_item.setData(Qt.UserRole, profile_id)
                table.setItem(row, 2, name_item)
                table.setItem(row, 3, QTableWidgetItem("On" if int(profile.get("scheduler_enabled", 1) or 0) == 1 else "Off"))
                table.setItem(row, 4, QTableWidgetItem(self._operating_profile_shell_summary(profile)))
                table.setItem(row, 5, QTableWidgetItem(str(profile.get("description", "") or "")))
        finally:
            self._operating_profiles_table_loading = False
        self._fit_table_height_to_rows(table, min_rows=1, max_rows=8, extra_rows=1)
        self._refresh_fit_content_section_height(getattr(self, "operating_profiles_section_group", None))
        if table.rowCount() > 0 and table.currentRow() < 0:
            table.selectRow(0)
        self._update_operating_profiles_hint()
        self._update_operating_profile_action_buttons()
        self._update_operating_profile_guidance_detail()
        if refresh_assignments:
            self._refresh_device_assignments_table(refresh_section_titles=False)
        if refresh_section_titles:
            self._refresh_section_titles()

    def _refresh_device_assignments_table(self, *, refresh_section_titles: bool = True) -> None:
        if not hasattr(self, "device_assignments_table"):
            return
        table = self.device_assignments_table
        try:
            if not self.device_profiles:
                self.device_profiles = list(self.multi_radio_store.list_device_profiles())
            if not self.operating_profiles:
                self.operating_profiles = list(self.multi_radio_store.list_operating_profiles())
            effective_assignments = {
                int(row.get("device_profile_id", 0) or 0): dict(row)
                for row in self.multi_radio_store.list_effective_assignments()
                if isinstance(row, dict)
            }
        except Exception:
            log.exception("Failed loading radio operating model assignments from store.")
            effective_assignments = {}
        try:
            active_swap = self.multi_radio_store.get_active_profile_swap()
        except Exception:
            log.exception("Failed loading active profile swap from store.")
            active_swap = None
        self.active_profile_swap = dict(active_swap) if isinstance(active_swap, dict) else None

        profiles = {
            int(row.get("id", 0) or 0): dict(row)
            for row in self.operating_profiles
            if isinstance(row, dict)
        }
        rows: List[Dict[str, Any]] = []
        for device in self.device_profiles:
            if not isinstance(device, dict):
                continue
            device_id = int(device.get("id", 0) or 0)
            assignment = effective_assignments.get(device_id, {})
            operating_id = assignment.get("operating_profile_id")
            operating = profiles.get(int(operating_id or 0)) if operating_id not in (None, "") else None
            rows.append(
                {
                    "device_profile_id": device_id,
                    "device_name": str(device.get("name", "") or ""),
                    "runtime_active": int(device.get("runtime_active", 0) or 0),
                    "runtime_primary": int(device.get("runtime_primary", 0) or 0),
                    "device_class": str(device.get("device_class", "") or ""),
                    "endpoint_summary": self._device_endpoint_summary(device),
                    "operating_profile_id": int(operating_id or 0) if operating_id not in (None, "") else None,
                    "operating_profile_name": str((operating or {}).get("name", "") or ""),
                    "operating_system_key": str((operating or {}).get("system_key", "") or ""),
                    "assignment_state": str(assignment.get("assignment_state", "") or ""),
                    "shell_summary": self._operating_profile_shell_summary(operating),
                }
            )
        self.device_assignments = rows

        self._device_assignments_table_loading = True
        try:
            table.setRowCount(0)
            for row_data in self.device_assignments:
                row = table.rowCount()
                table.insertRow(row)
                device_profile_id = int(row_data.get("device_profile_id", 0) or 0)

                sel_chk = QCheckBox()
                sel_chk.setFixedWidth(22)
                sel_chk.setProperty("device_profile_id", device_profile_id)
                sel_chk.stateChanged.connect(self._update_device_assignment_action_buttons)
                sel_wrap = QWidget()
                sel_layout = QHBoxLayout(sel_wrap)
                sel_layout.setContentsMargins(0, 0, 0, 0)
                sel_layout.setAlignment(Qt.AlignCenter)
                sel_layout.addWidget(sel_chk)
                table.setCellWidget(row, 0, sel_wrap)

                active_item = QTableWidgetItem("Yes" if int(row_data.get("runtime_active", 0) or 0) == 1 else "")
                active_item.setTextAlignment(Qt.AlignCenter)
                table.setItem(row, 1, active_item)

                primary_item = QTableWidgetItem("Yes" if int(row_data.get("runtime_primary", 0) or 0) == 1 else "")
                primary_item.setTextAlignment(Qt.AlignCenter)
                table.setItem(row, 2, primary_item)
                device_item = QTableWidgetItem(str(row_data.get("device_name", "") or ""))
                device_item.setData(Qt.UserRole, device_profile_id)
                table.setItem(row, 3, device_item)
                table.setItem(row, 4, QTableWidgetItem(str(row_data.get("operating_profile_name", "") or "Unassigned")))
                table.setItem(row, 5, QTableWidgetItem(self._assignment_state_label(str(row_data.get("assignment_state", "") or ""))))
                table.setItem(row, 6, QTableWidgetItem(str(row_data.get("shell_summary", "") or "")))
        finally:
            self._device_assignments_table_loading = False
        self._fit_table_height_to_rows(table, min_rows=1, max_rows=8, extra_rows=1)
        if table.rowCount() > 0 and table.currentRow() < 0:
            table.selectRow(0)
        self._update_device_assignments_hint()
        self._refresh_radio_context_labels()
        self._update_device_assignment_action_buttons()
        self._update_device_assignments_guidance_detail()
        if refresh_section_titles:
            self._refresh_section_titles()

    def _schedule_assignment_guard_status(self, assignment: Mapping[str, Any]) -> str:
        raw = assignment.get("validation_status_json", "") if isinstance(assignment, Mapping) else ""
        try:
            data = json.loads(str(raw or "{}"))
        except Exception:
            data = {}
        if str(data.get("rf_guard_validation", "") or "").strip().lower() == "not_enforced":
            return "Not enforced"
        state = str(data.get("state", "") or "").strip().lower()
        if state == "blocked":
            return "Blocked"
        if state == "warning":
            return "Needs review"
        if state == "ok":
            return "Ready"
        return "--"

    def _selected_schedule_assignment_rows(self) -> List[Dict[str, Any]]:
        if not hasattr(self, "schedule_assignments_table"):
            return []
        selected: List[Dict[str, Any]] = []
        seen_device_ids: set[int] = set()

        def append_assignment_for_device(device_profile_id: int) -> None:
            if device_profile_id <= 0 or device_profile_id in seen_device_ids:
                return
            match = next(
                (
                    dict(item)
                    for item in getattr(self, "schedule_assignments", [])
                    if isinstance(item, dict) and int(item.get("device_profile_id", 0) or 0) == device_profile_id
                ),
                None,
            )
            if match is not None:
                selected.append(match)
                seen_device_ids.add(device_profile_id)

        for row in range(self.schedule_assignments_table.rowCount()):
            wrapper = self.schedule_assignments_table.cellWidget(row, 0)
            chk = wrapper.findChild(QCheckBox) if wrapper is not None else None
            if chk is None or not chk.isChecked():
                continue
            try:
                device_profile_id = int(chk.property("device_profile_id") or 0)
            except Exception:
                continue
            append_assignment_for_device(device_profile_id)
        if selected:
            return selected
        selection_model = self.schedule_assignments_table.selectionModel()
        selected_rows = selection_model.selectedRows() if selection_model is not None else []
        for index in selected_rows:
            row = int(index.row())
            wrapper = self.schedule_assignments_table.cellWidget(row, 0)
            chk = wrapper.findChild(QCheckBox) if wrapper is not None else None
            try:
                device_profile_id = int(chk.property("device_profile_id") or 0) if chk is not None else 0
            except Exception:
                device_profile_id = 0
            if device_profile_id <= 0 and 0 <= row < len(getattr(self, "schedule_assignments", [])):
                try:
                    device_profile_id = int(self.schedule_assignments[row].get("device_profile_id", 0) or 0)
                except Exception:
                    device_profile_id = 0
            append_assignment_for_device(device_profile_id)
        return selected

    def _update_schedule_assignment_action_buttons(self) -> None:
        if not hasattr(self, "assign_schedule_btn"):
            return
        theme = resolve_theme(self.settings)
        selected = self._selected_schedule_assignment_rows()
        can_assign = bool(getattr(self, "frequency_plans", []))
        can_swap = (
            len(selected) == 2
            and all(int(row.get("frequency_plan_id") or 0) > 0 for row in selected)
            and int(selected[0].get("frequency_plan_id") or 0) != int(selected[1].get("frequency_plan_id") or 0)
        )
        self.assign_schedule_btn.setEnabled(can_assign)
        self.assign_schedule_btn.setStyleSheet(button_style("info" if can_assign else "muted", theme))
        if hasattr(self, "swap_schedule_plans_btn"):
            self.swap_schedule_plans_btn.setEnabled(can_swap)
            self.swap_schedule_plans_btn.setStyleSheet(button_style("warning" if can_swap else "muted", theme))
            if can_swap:
                first = str(selected[0].get("device_name", "") or "first radio").strip()
                second = str(selected[1].get("device_name", "") or "second radio").strip()
                self.swap_schedule_plans_btn.setToolTip(
                    f"Swap assigned Frequency Plans between {first} and {second}. RF Guard validates the post-swap state before saving."
                )
            else:
                self.swap_schedule_plans_btn.setToolTip(
                    "Select exactly two radios that already have different assigned Frequency Plans."
                )

    def _swap_selected_schedule_assignments(self) -> None:
        selected = self._selected_schedule_assignment_rows()
        if len(selected) != 2:
            self._set_schedule_assignment_guidance(
                "Schedule Assignment",
                "Select exactly two radios with assigned Frequency Plans to swap.",
                "warning",
            )
            return
        try:
            first_id = int(selected[0].get("device_profile_id") or 0)
            second_id = int(selected[1].get("device_profile_id") or 0)
        except Exception:
            first_id = second_id = 0
        if first_id <= 0 or second_id <= 0 or first_id == second_id:
            self._set_schedule_assignment_guidance(
                "Schedule Assignment",
                "Select two different radios before swapping plans.",
                "warning",
            )
            return
        try:
            self.multi_radio_store.swap_assigned_frequency_plans(first_id, second_id)
        except ValueError as exc:
            self._set_schedule_assignment_guidance("RF Guard Blocked Plan Swap", str(exc), "warning")
            return
        except Exception:
            log.exception("Failed swapping schedule assignments.")
            self._set_schedule_assignment_guidance(
                "Schedule Assignment",
                "Unable to swap the selected schedule assignments.",
                "danger",
            )
            return
        self._refresh_multi_radio_tables()
        self._refresh_schedule_assignments_table(refresh_section_titles=False)
        self._emit_device_profiles_changed()
        self._set_save_button_state("info" if self._settings_dirty else "success")
        first_name = str(selected[0].get("device_name", "") or "first radio").strip()
        second_name = str(selected[1].get("device_name", "") or "second radio").strip()
        self._set_schedule_assignment_guidance(
            "Schedule Assignment Saved",
            f"Swapped assigned Frequency Plans between {first_name} and {second_name} with RF Guard.",
            "success",
        )
        self._publish_settings_action_feedback(
            status="succeeded",
            summary=f"Swapped schedule assignments between {first_name} and {second_name}.",
            action_type="schedule_assignment_swap",
        )

    def _set_schedule_assignment_guidance(self, title: str, text: str, level: str = "info") -> None:
        if not hasattr(self, "schedule_assignments_guidance_card"):
            return
        editor_visible = bool(
            hasattr(self, "schedule_assignment_editor_panel")
            and self.schedule_assignment_editor_panel.isVisible()
        )
        if editor_visible and str(level or "").strip().lower() in {"info", "success"}:
            self.schedule_assignments_guidance_card.setVisible(False)
            self._refresh_fit_content_section_height(getattr(self, "schedule_assignments_section_group", None))
            return
        self.schedule_assignments_guidance_card.setVisible(True)
        self._set_guidance_card_state(
            self.schedule_assignments_guidance_card,
            self.schedule_assignments_guidance_title_label,
            self.schedule_assignments_guidance_status_label,
            title=title,
            text=text,
            level=level,
        )

    def _selected_schedule_frequency_plan(self) -> Optional[Dict[str, Any]]:
        if not hasattr(self, "schedule_assignment_plan_combo"):
            return None
        try:
            plan_id = int(self.schedule_assignment_plan_combo.currentData() or 0)
        except Exception:
            plan_id = 0
        if plan_id <= 0:
            return None
        return next(
            (
                dict(row)
                for row in getattr(self, "frequency_plans", [])
                if isinstance(row, dict) and int(row.get("id", 0) or 0) == plan_id
            ),
            None,
        )

    def _schedule_assignment_row_for_device_id(self, device_profile_id: int) -> Optional[Dict[str, Any]]:
        try:
            target_id = int(device_profile_id)
        except Exception:
            target_id = 0
        if target_id <= 0:
            return None
        return next(
            (
                dict(row)
                for row in getattr(self, "schedule_assignments", [])
                if isinstance(row, dict) and int(row.get("device_profile_id", 0) or 0) == target_id
            ),
            None,
        )

    def _default_schedule_assignment_radio_id(self) -> int:
        rows = [row for row in getattr(self, "schedule_assignments", []) if isinstance(row, dict)]
        for key in ("runtime_active", "runtime_primary"):
            for row in rows:
                try:
                    if int(row.get(key, 0) or 0) == 1:
                        radio_id = int(row.get("device_profile_id", 0) or 0)
                        if radio_id > 0:
                            return radio_id
                except Exception:
                    continue
        if rows:
            try:
                return int(rows[0].get("device_profile_id", 0) or 0)
            except Exception:
                return 0
        return 0

    def _hide_schedule_assignment_editor(self) -> None:
        if hasattr(self, "schedule_assignment_editor_panel"):
            self.schedule_assignment_editor_panel.setVisible(False)
        self.schedule_assignment_editor_rows = []
        self._refresh_fit_content_section_height(getattr(self, "schedule_assignments_section_group", None))

    def _refresh_schedule_assignment_editor_summary(self) -> None:
        if not hasattr(self, "schedule_assignment_editor_summary_label"):
            return
        rows = [row for row in getattr(self, "schedule_assignment_editor_rows", []) if isinstance(row, dict)]
        if not rows:
            self.schedule_assignment_editor_summary_label.setText("Choose the radio and Frequency Plan to assign.")
            return
        row = rows[0]
        name = str(row.get("device_name", "") or f"Radio {int(row.get('device_profile_id', 0) or 0)}").strip()
        current_plan = str(row.get("frequency_plan_name", "") or "Unassigned").strip()
        self.schedule_assignment_editor_summary_label.setText(
            f"Assign a Frequency Plan to {name or 'the selected radio'}. Current assignment: {current_plan}."
        )

    def _on_schedule_assignment_radio_changed(self, *_args) -> None:
        if getattr(self, "_schedule_assignment_radio_combo_loading", False):
            return
        if not hasattr(self, "schedule_assignment_radio_combo"):
            return
        try:
            device_profile_id = int(self.schedule_assignment_radio_combo.currentData() or 0)
        except Exception:
            device_profile_id = 0
        row = self._schedule_assignment_row_for_device_id(device_profile_id)
        self.schedule_assignment_editor_rows = [row] if row is not None else []
        if row is not None:
            try:
                current_plan_id = int(row.get("frequency_plan_id") or 0)
            except Exception:
                current_plan_id = 0
            if current_plan_id > 0 and hasattr(self, "schedule_assignment_plan_combo"):
                idx = self.schedule_assignment_plan_combo.findData(current_plan_id)
                if idx >= 0:
                    self.schedule_assignment_plan_combo.setCurrentIndex(idx)
            state = str(row.get("assignment_state", "") or "active").strip().lower()
            state_idx = self.schedule_assignment_state_combo.findData(state)
            self.schedule_assignment_state_combo.setCurrentIndex(state_idx if state_idx >= 0 else 0)
        self._refresh_schedule_assignment_editor_summary()
        self._update_schedule_assignment_editor_hint()

    def _schedule_assignment_validation_message(self, validation: Mapping[str, Any]) -> Tuple[str, str]:
        blocked = [str(item).strip() for item in validation.get("blocked", []) if str(item).strip()]
        warnings = [str(item).strip() for item in validation.get("warnings", []) if str(item).strip()]
        if not blocked and not warnings:
            return "", ""
        supported = [str(item).strip() for item in validation.get("supported_bands", []) if str(item).strip()]
        plan_bands = [str(item).strip() for item in validation.get("plan_bands", []) if str(item).strip()]
        unsupported = [band for band in plan_bands if supported and band not in supported]
        if unsupported and supported:
            detail = (
                f"Antenna and schedule mismatch: this radio supports {self._human_join(supported)}, "
                f"but the selected plan uses {self._human_join(unsupported)}. "
                "Choose a different plan, update the supported antenna bands, or do not transmit until the antenna path is confirmed."
            )
        else:
            detail = blocked[0] if blocked else warnings[0]
        return ("blocked" if blocked else "warning"), detail

    def _update_schedule_assignment_editor_hint(self) -> None:
        if not hasattr(self, "schedule_assignment_editor_hint_label"):
            return
        rows = [row for row in getattr(self, "schedule_assignment_editor_rows", []) if isinstance(row, dict)]
        selected_has_observer = any(
            str(row.get("device_class", "") or "").strip().lower() == "observer"
            for row in rows
        )
        plan = self._selected_schedule_frequency_plan()
        state = str(self.schedule_assignment_state_combo.currentData() or "active").strip().lower()
        bits: List[str] = []
        if selected_has_observer:
            if plan and int(plan.get("receive_only", 0) or 0) != 1:
                bits.append("Observer / SDR radios can only use receive-only schedule plans.")
            else:
                bits.append("Observer / SDR radios require a receive-only schedule plan.")
        if state == "temporary_override":
            bits.append("Temporary Override applies immediately. Ends UTC is metadata in this checkpoint.")
        else:
            bits.append("Active assignments become the current schedule plan for the selected radio immediately.")
        bits.append("Save with RF Guard runs the assignment check before the radio schedule changes.")
        if len(rows) == 1 and plan is not None:
            try:
                device_id = int(rows[0].get("device_profile_id", 0) or 0)
            except Exception:
                device_id = 0
            warning_tone = ""
            warning_detail = ""
            if device_id > 0:
                try:
                    validation = self.multi_radio_store.validate_frequency_plan_for_device(device_id, plan)
                except ValueError as exc:
                    warning_tone = "blocked"
                    warning_detail = str(exc)
                    bits.append(f"RF Guard blocked: {warning_detail}")
                except Exception:
                    log.exception("Failed validating selected schedule assignment.")
                else:
                    tone, detail = self._schedule_assignment_validation_message(validation)
                    if tone and detail:
                        warning_tone = tone
                        warning_detail = detail
                        bits.append(f"RF Guard {tone}: {detail}")
            if warning_tone and warning_detail:
                self._set_schedule_assignment_guidance(
                    "RF Guard Blocked Assignment" if warning_tone == "blocked" else "RF Guard Needs Review",
                    warning_detail,
                    "warning",
                )
        self.schedule_assignment_editor_hint_label.setText(" ".join(bits))

    def _show_schedule_assignment_editor(
        self,
        selected_devices: List[Dict[str, Any]],
        *,
        preferred_plan_id: int = 0,
        preferred_device_profile_id: int = 0,
    ) -> None:
        try:
            self.frequency_plans = list(self.multi_radio_store.list_frequency_plans())
        except Exception:
            log.exception("Failed loading frequency plans for schedule assignment editor.")
            self.frequency_plans = []
        enabled_plans = [
            row
            for row in self.frequency_plans
            if isinstance(row, dict)
            and int(row.get("enabled", 1) or 0) == 1
            and str(row.get("category") or "").strip().lower() not in SOURCE_ONLY_FREQUENCY_PLAN_CATEGORIES
        ]
        if not enabled_plans:
            self._set_schedule_assignment_guidance(
                "Schedule Assignment",
                "No built Frequency Plans are available yet. Build a schedule in Plan Builder before assigning it to radios.",
                "warning",
            )
            return
        selected_rows = [dict(row) for row in selected_devices if isinstance(row, dict)]
        try:
            target_device_id = int(preferred_device_profile_id or 0)
        except Exception:
            target_device_id = 0
        if target_device_id <= 0 and selected_rows:
            try:
                target_device_id = int(selected_rows[0].get("device_profile_id", 0) or 0)
            except Exception:
                target_device_id = 0
        if target_device_id <= 0:
            target_device_id = self._default_schedule_assignment_radio_id()
        target_row = self._schedule_assignment_row_for_device_id(target_device_id)
        if target_row is None and selected_rows:
            target_row = selected_rows[0]
        self.schedule_assignment_editor_rows = [target_row] if target_row is not None else []

        if hasattr(self, "schedule_assignment_radio_combo"):
            self._schedule_assignment_radio_combo_loading = True
            self.schedule_assignment_radio_combo.blockSignals(True)
            self.schedule_assignment_radio_combo.clear()
            for assignment in getattr(self, "schedule_assignments", []):
                if not isinstance(assignment, dict):
                    continue
                radio_id = int(assignment.get("device_profile_id", 0) or 0)
                if radio_id <= 0:
                    continue
                label = str(assignment.get("device_name", "") or f"Radio {radio_id}").strip()
                current = str(assignment.get("frequency_plan_name", "") or "Unassigned").strip()
                self.schedule_assignment_radio_combo.addItem(f"{label} - {current}", radio_id)
            if target_device_id > 0:
                idx = self.schedule_assignment_radio_combo.findData(target_device_id)
                if idx >= 0:
                    self.schedule_assignment_radio_combo.setCurrentIndex(idx)
            self.schedule_assignment_radio_combo.blockSignals(False)
            self._schedule_assignment_radio_combo_loading = False
        self._refresh_schedule_assignment_editor_summary()

        current_plan_id = int(preferred_plan_id or 0)
        if current_plan_id <= 0 and len(self.schedule_assignment_editor_rows) == 1:
            try:
                current_plan_id = int(self.schedule_assignment_editor_rows[0].get("frequency_plan_id") or 0)
            except Exception:
                current_plan_id = 0
        self.schedule_assignment_plan_combo.blockSignals(True)
        self.schedule_assignment_plan_combo.clear()
        for row in enabled_plans:
            label = str(row.get("name", "") or "Frequency Plan")
            if int(row.get("receive_only", 0) or 0) == 1:
                label = f"{label} (receive-only)"
            self.schedule_assignment_plan_combo.addItem(label, int(row.get("id", 0) or 0))
        if current_plan_id > 0:
            idx = self.schedule_assignment_plan_combo.findData(current_plan_id)
            if idx >= 0:
                self.schedule_assignment_plan_combo.setCurrentIndex(idx)
        self.schedule_assignment_plan_combo.blockSignals(False)

        if len(self.schedule_assignment_editor_rows) == 1:
            state = str(self.schedule_assignment_editor_rows[0].get("assignment_state", "") or "active").strip().lower()
            state_idx = self.schedule_assignment_state_combo.findData(state)
            self.schedule_assignment_state_combo.setCurrentIndex(state_idx if state_idx >= 0 else 0)
        else:
            self.schedule_assignment_state_combo.setCurrentIndex(0)
        self.schedule_assignment_reason_edit.clear()
        self.schedule_assignment_ends_edit.clear()
        self.schedule_assignment_editor_panel.setVisible(True)
        self._update_schedule_assignment_editor_hint()
        self._set_schedule_assignment_guidance(
            "Schedule Assignment",
            "Review the schedule assignment in this panel, then save or cancel without leaving Settings.",
            "info",
        )
        self._refresh_fit_content_section_height(getattr(self, "schedule_assignments_section_group", None))

    def open_schedule_assignment_editor(self, *, plan_id: int = 0, device_profile_id: int = 0) -> bool:
        if not hasattr(self, "schedule_assignments_table"):
            return False
        group = getattr(self, "schedule_assignments_section_group", None)
        if group is not None:
            self._select_settings_section_group(group)
        self._refresh_schedule_assignments_table(refresh_section_titles=False)
        selected_device_id = int(device_profile_id or 0)
        if selected_device_id <= 0:
            selected_device_id = self._default_schedule_assignment_radio_id()
        selected = []
        row = self._schedule_assignment_row_for_device_id(selected_device_id)
        if row is not None:
            selected = [row]
        self._show_schedule_assignment_editor(
            selected,
            preferred_plan_id=int(plan_id or 0),
            preferred_device_profile_id=selected_device_id,
        )
        return True

    def _save_schedule_assignment_editor(self) -> None:
        selected = [row for row in getattr(self, "schedule_assignment_editor_rows", []) if isinstance(row, dict)]
        if not selected:
            self._set_schedule_assignment_guidance("Schedule Assignment", "Select one or more radios first.", "warning")
            return
        try:
            plan_id = int(self.schedule_assignment_plan_combo.currentData() or 0)
        except Exception:
            plan_id = 0
        if plan_id <= 0:
            self._set_schedule_assignment_guidance("Schedule Assignment", "Select a Frequency Plan.", "warning")
            return
        selected_plan = self._selected_schedule_frequency_plan()
        if any(str(row.get("device_class", "") or "").strip().lower() == "observer" for row in selected):
            if int((selected_plan or {}).get("receive_only", 0) or 0) != 1:
                self._set_schedule_assignment_guidance(
                    "Schedule Assignment",
                    "Observer / SDR radios can only be assigned receive-only schedule plans. No schedule assignments were changed.",
                    "warning",
                )
                return
        state = str(self.schedule_assignment_state_combo.currentData() or "active").strip().lower() or "active"
        reason_value = self.schedule_assignment_reason_edit.text().strip()
        if state == "temporary_override" and not reason_value:
            reason_value = "Temporary schedule override from Settings."
        ends_value = self.schedule_assignment_ends_edit.text().strip()
        saved_assignments: List[Dict[str, Any]] = []
        try:
            for row in selected:
                saved = self.multi_radio_store.set_assigned_plan(
                    int(row.get("device_profile_id", 0) or 0),
                    plan_id,
                    assignment_state=state,
                    reason=reason_value,
                    ends_utc=ends_value,
                )
                if isinstance(saved, dict):
                    saved_assignments.append(saved)
        except ValueError as exc:
            self._set_schedule_assignment_guidance("RF Guard Blocked Assignment", str(exc), "warning")
            return
        except Exception:
            log.exception("Failed updating schedule assignments.")
            self._set_schedule_assignment_guidance(
                "Schedule Assignment",
                "Unable to update the selected schedule assignment.",
                "danger",
            )
            return
        saved_device_id = 0
        try:
            saved_device_id = int(selected[0].get("device_profile_id", 0) or 0)
        except Exception:
            saved_device_id = 0
        self._refresh_multi_radio_tables()
        self._refresh_schedule_assignments_table(refresh_section_titles=False)
        refreshed_row = self._schedule_assignment_row_for_device_id(saved_device_id)
        self._show_schedule_assignment_editor(
            [refreshed_row] if refreshed_row is not None else selected[:1],
            preferred_plan_id=int(plan_id or 0),
            preferred_device_profile_id=saved_device_id,
        )
        self._emit_device_profiles_changed()
        self._set_save_button_state("info" if self._settings_dirty else "success")
        warning_text = ""
        warning_tone = "warning"
        for assignment in saved_assignments:
            try:
                validation = json.loads(str(assignment.get("validation_status_json", "") or "{}"))
            except Exception:
                validation = {}
            tone, detail = self._schedule_assignment_validation_message(validation)
            if detail:
                warning_text = detail
                warning_tone = tone or "warning"
                break
        if warning_text:
            self._set_schedule_assignment_guidance(
                "RF Guard Blocked Assignment" if warning_tone == "blocked" else "RF Guard Needs Review",
                warning_text,
                "warning",
            )
        else:
            self._set_schedule_assignment_guidance(
                "Schedule Assignment Saved",
                f"Saved with RF Guard for {len(selected)} radio{'s' if len(selected) != 1 else ''}.",
                "success",
            )
        self._publish_settings_action_feedback(
            status="succeeded",
            summary=f"Updated schedule assignment for {len(selected)} radio{'s' if len(selected) != 1 else ''}.",
            action_type="schedule_assignment",
        )

    def _assign_frequency_plan_to_selected_radios(self) -> None:
        selected = self._selected_schedule_assignment_rows()
        if not selected:
            selected_id = self._default_schedule_assignment_radio_id()
            row = self._schedule_assignment_row_for_device_id(selected_id)
            selected = [row] if row is not None else []
        self._show_schedule_assignment_editor(selected)

    def _refresh_schedule_assignments_table(self, *, refresh_section_titles: bool = True) -> None:
        if not hasattr(self, "schedule_assignments_table"):
            return
        table = self.schedule_assignments_table
        try:
            if not self.device_profiles:
                self.device_profiles = list(self.multi_radio_store.list_device_profiles())
            self.frequency_plans = list(self.multi_radio_store.list_frequency_plans())
            effective_assignments = {
                int(row.get("device_profile_id", 0) or 0): dict(row)
                for row in self.multi_radio_store.list_effective_assigned_plans()
                if isinstance(row, dict)
            }
        except Exception:
            log.exception("Failed loading radio schedule assignments from store.")
            self.frequency_plans = []
            effective_assignments = {}
        plans = {
            int(row.get("id", 0) or 0): dict(row)
            for row in self.frequency_plans
            if isinstance(row, dict)
        }
        rows: List[Dict[str, Any]] = []
        for device in self.device_profiles:
            if not isinstance(device, dict):
                continue
            device_id = int(device.get("id", 0) or 0)
            assignment = effective_assignments.get(device_id, {})
            plan_id = assignment.get("frequency_plan_id")
            plan = plans.get(int(plan_id or 0)) if plan_id not in (None, "") else None
            rows.append(
                {
                    "device_profile_id": device_id,
                    "device_name": str(device.get("name", "") or ""),
                    "runtime_active": int(device.get("runtime_active", 0) or 0),
                    "runtime_primary": int(device.get("runtime_primary", 0) or 0),
                    "device_class": str(device.get("device_class", "") or ""),
                    "endpoint_summary": self._device_endpoint_summary(device),
                    "frequency_plan_id": int(plan_id or 0) if plan_id not in (None, "") else None,
                    "frequency_plan_name": str((plan or {}).get("name", "") or ""),
                    "assignment_state": str(assignment.get("assignment_state", "") or ""),
                    "guard_status": self._schedule_assignment_guard_status(assignment),
                }
            )
        self.schedule_assignments = rows
        try:
            table.setRowCount(0)
            for row_data in self.schedule_assignments:
                row = table.rowCount()
                table.insertRow(row)
                device_profile_id = int(row_data.get("device_profile_id", 0) or 0)
                sel_chk = QCheckBox()
                sel_chk.setFixedWidth(22)
                sel_chk.setProperty("device_profile_id", device_profile_id)
                sel_chk.stateChanged.connect(self._update_schedule_assignment_action_buttons)
                sel_wrap = QWidget()
                sel_layout = QHBoxLayout(sel_wrap)
                sel_layout.setContentsMargins(0, 0, 0, 0)
                sel_layout.setAlignment(Qt.AlignCenter)
                sel_layout.addWidget(sel_chk)
                table.setCellWidget(row, 0, sel_wrap)

                active_item = QTableWidgetItem("Yes" if int(row_data.get("runtime_active", 0) or 0) == 1 else "")
                active_item.setTextAlignment(Qt.AlignCenter)
                table.setItem(row, 1, active_item)
                primary_item = QTableWidgetItem("Yes" if int(row_data.get("runtime_primary", 0) or 0) == 1 else "")
                primary_item.setTextAlignment(Qt.AlignCenter)
                table.setItem(row, 2, primary_item)
                device_item = QTableWidgetItem(str(row_data.get("device_name", "") or ""))
                device_item.setData(Qt.UserRole, device_profile_id)
                table.setItem(row, 3, device_item)
                table.setItem(row, 4, QTableWidgetItem(str(row_data.get("frequency_plan_name", "") or "Unassigned")))
                table.setItem(row, 5, QTableWidgetItem(self._assignment_state_label(str(row_data.get("assignment_state", "") or ""))))
                table.setItem(row, 6, QTableWidgetItem(str(row_data.get("guard_status", "") or "--")))
        finally:
            pass
        self._fit_table_height_to_rows(table, min_rows=1, max_rows=8, extra_rows=1)
        if table.rowCount() > 0 and table.currentRow() < 0:
            table.selectRow(0)
        self._update_schedule_assignment_action_buttons()
        if not self.frequency_plans:
            self._set_schedule_assignment_guidance(
                "Schedule Assignment",
                "No built Frequency Plans are available yet. Build a schedule in Plan Builder before assigning it to radios.",
                "warning",
            )
        else:
            self._set_schedule_assignment_guidance(
                "Schedule Assignment",
                "Assign built Frequency Plans to radios here. Save with RF Guard checks the selected radio before the schedule changes.",
                "info",
            )
        if refresh_section_titles:
            self._refresh_section_titles()

    def _open_operating_profile_dialog(self, existing: Optional[Dict[str, Any]] = None) -> Optional[Dict[str, Any]]:
        dlg = QDialog(self)
        dlg.setWindowTitle("Edit Operating Model" if existing else "Add Operating Model")
        dlg.resize(560, 0)
        layout = QVBoxLayout(dlg)
        form = QFormLayout()
        form.setFieldGrowthPolicy(QFormLayout.ExpandingFieldsGrow)
        layout.addLayout(form)

        name_edit = QLineEdit(str((existing or {}).get("name", "") or ""))
        form.addRow("Name:", name_edit)

        enabled_chk = QCheckBox("Model Enabled")
        enabled_chk.setChecked(bool((existing or {}).get("enabled", 1)))
        form.addRow("", enabled_chk)

        description_edit = QPlainTextEdit(str((existing or {}).get("description", "") or ""))
        description_edit.setMinimumHeight(
            multiline_height_for_font(description_edit, visible_lines=3)
        )
        form.addRow("Description:", description_edit)

        scheduler_enabled_chk = QCheckBox("Enable scheduler automation when primary")
        scheduler_enabled_chk.setChecked(bool((existing or {}).get("scheduler_enabled", 1)))
        form.addRow("", scheduler_enabled_chk)

        scheduler_mode_combo = QComboBox()
        for label, value in OPERATING_SCHEDULER_MODE_OPTIONS:
            scheduler_mode_combo.addItem(label, value)
        current_mode = str((existing or {}).get("scheduler_mode", "full") or "full").strip().lower()
        mode_idx = scheduler_mode_combo.findData(current_mode)
        scheduler_mode_combo.setCurrentIndex(mode_idx if mode_idx >= 0 else 0)
        self._fit_combo_to_contents(scheduler_mode_combo, minimum=220)
        scheduler_mode_combo.setToolTip(
            "Choose the default CommsPlan feature preset for this operating model. The checkboxes below show exactly what the preset includes."
        )
        form.addRow("Workflow Preset:", scheduler_mode_combo)

        preferred_bands_edit = QLineEdit(
            self._preferred_band_text(
                (existing or {}).get("preferred_band_set_json", (existing or {}).get("preferred_band_set", ""))
            )
        )
        preferred_bands_edit.setPlaceholderText("Optional observer/SDR standby bands, e.g. 40M, 80M")
        preferred_bands_edit.setToolTip(
            "Used by observer/SDR follow behavior. This is not an antenna safety or band-overlap guard."
        )
        form.addRow("Observer Standby Bands:", preferred_bands_edit)

        use_messages_chk = QCheckBox("Use Messages")
        use_messages_chk.setChecked(bool((existing or {}).get("use_messages", 1)))
        form.addRow("", use_messages_chk)

        use_map_chk = QCheckBox("Use Map")
        use_map_chk.setChecked(bool((existing or {}).get("use_map", 1)))
        form.addRow("", use_map_chk)

        use_background_ingest_chk = QCheckBox("Use background ingest")
        use_background_ingest_chk.setChecked(bool((existing or {}).get("use_background_ingest", 1)))
        form.addRow("", use_background_ingest_chk)

        use_launch_control_chk = QCheckBox("Use Launch Control")
        use_launch_control_chk.setChecked(bool((existing or {}).get("use_launch_control", 0)))
        form.addRow("", use_launch_control_chk)

        use_net_control_tabs_chk = QCheckBox("Use net control tabs")
        use_net_control_tabs_chk.setChecked(bool((existing or {}).get("use_net_control_tabs", 1)))
        form.addRow("", use_net_control_tabs_chk)

        receive_only_chk = QCheckBox("Receive-only model (observer / SDR compatible)")
        receive_only_chk.setChecked(bool((existing or {}).get("receive_only", 0)))
        form.addRow("", receive_only_chk)

        allow_profile_swap_chk = QCheckBox("Allow assignment swap coordination")
        allow_profile_swap_chk.setChecked(bool((existing or {}).get("allow_profile_swap", 0)))
        form.addRow("", allow_profile_swap_chk)

        info_label = QLabel()
        info_label.setWordWrap(True)
        form.addRow("", info_label)

        def _update_hint() -> None:
            disabled: List[str] = []
            if not scheduler_enabled_chk.isChecked():
                disabled.append("scheduler automation")
            if not use_messages_chk.isChecked():
                disabled.append("Messages")
            if not use_map_chk.isChecked():
                disabled.append("Map")
            if not use_background_ingest_chk.isChecked():
                disabled.append("background ingest")
            if not use_launch_control_chk.isChecked():
                disabled.append("Launch Control")
            if not use_net_control_tabs_chk.isChecked():
                disabled.append("net control tabs")
            prefix = (
                "Receive-only model: can be assigned to observer / SDR radios and should not be used as a transmit target. "
                if receive_only_chk.isChecked()
                else "Transmit-capable model: use with transmit/receive radios. "
            )
            if disabled:
                info_label.setText(
                    prefix
                    + "When this operating model applies to the Station Default radio, it suppresses: "
                    + ", ".join(disabled)
                    + "."
                )
            else:
                info_label.setText(
                    prefix
                    + "This operating model leaves the current Station Default compatibility shell fully enabled."
                )

        for chk in (
            scheduler_enabled_chk,
            use_messages_chk,
            use_map_chk,
            use_background_ingest_chk,
            use_launch_control_chk,
            use_net_control_tabs_chk,
            receive_only_chk,
        ):
            chk.toggled.connect(_update_hint)
        _update_hint()

        buttons = QDialogButtonBox(QDialogButtonBox.Save | QDialogButtonBox.Cancel)
        layout.addWidget(buttons)

        out: Dict[str, Any] = {}

        def _save() -> None:
            name = name_edit.text().strip()
            if not name:
                QMessageBox.warning(self, "Validation", "Operating model name is required.")
                return
            out.update(
                {
                    "id": (existing or {}).get("id"),
                    "system_key": (existing or {}).get("system_key"),
                    "name": name,
                    "enabled": bool(enabled_chk.isChecked()),
                    "description": description_edit.toPlainText().strip(),
                    "scheduler_enabled": bool(scheduler_enabled_chk.isChecked()),
                    "scheduler_mode": str(scheduler_mode_combo.currentData() or "full"),
                    "preferred_band_set": preferred_bands_edit.text().strip(),
                    "use_messages": bool(use_messages_chk.isChecked()),
                    "use_map": bool(use_map_chk.isChecked()),
                    "use_background_ingest": bool(use_background_ingest_chk.isChecked()),
                    "use_launch_control": bool(use_launch_control_chk.isChecked()),
                    "use_net_control_tabs": bool(use_net_control_tabs_chk.isChecked()),
                    "receive_only": bool(receive_only_chk.isChecked()),
                    "allow_profile_swap": bool(allow_profile_swap_chk.isChecked()),
                }
            )
            dlg.accept()

        buttons.accepted.connect(_save)
        buttons.rejected.connect(dlg.reject)
        if dlg.exec() != QDialog.Accepted:
            return None
        return out if out else None

    def _persist_operating_profile(self, values: Dict[str, Any]) -> None:
        try:
            self.multi_radio_store.save_operating_profile(values)
        except ValueError as exc:
            QMessageBox.warning(self, "Operating Models", str(exc))
            return
        except Exception:
            log.exception("Failed to save operating profile.")
            QMessageBox.warning(self, "Operating Models", "Unable to save the operating model.")
            return
        self._refresh_multi_radio_tables()
        self._emit_device_profiles_changed()
        self._set_save_button_state("info" if self._settings_dirty else "success")

    def _add_operating_profile(self) -> None:
        created = self._open_operating_profile_dialog(existing=None)
        if not created:
            return
        self._persist_operating_profile(created)

    def _edit_operating_profile(self) -> None:
        selected = self._selected_operating_profiles()
        if not selected:
            QMessageBox.information(self, "Edit Operating Model", "Select one operating model to edit.")
            return
        if len(selected) > 1:
            QMessageBox.warning(self, "Edit Operating Model", "Please select only one operating model to edit.")
            return
        updated = self._open_operating_profile_dialog(existing=selected[0])
        if not updated:
            return
        self._persist_operating_profile(updated)

    def _delete_operating_profiles(self) -> None:
        selected = self._selected_operating_profiles()
        if not selected:
            QMessageBox.information(self, "Delete Operating Models", "Select one or more operating models to delete.")
            return
        confirm = QMessageBox.question(
            self,
            "Delete Operating Models",
            f"Delete {len(selected)} selected operating model(s)?",
            QMessageBox.Yes | QMessageBox.No,
            QMessageBox.No,
        )
        if confirm != QMessageBox.Yes:
            return
        try:
            for row in selected:
                self.multi_radio_store.delete_operating_profile(int(row.get("id", 0) or 0))
        except ValueError as exc:
            QMessageBox.warning(self, "Delete Operating Models", str(exc))
            self._refresh_multi_radio_tables()
            return
        except Exception:
            log.exception("Failed deleting operating profiles.")
            QMessageBox.warning(self, "Delete Operating Models", "Unable to delete the selected operating models.")
            return
        self._refresh_multi_radio_tables()
        self._emit_device_profiles_changed()
        self._set_save_button_state("info" if self._settings_dirty else "success")
        QMessageBox.information(
            self,
            "Delete Operating Models",
            f"Deleted {len(selected)} operating model{'s' if len(selected) != 1 else ''}.",
        )

    def _assignment_editor_selected_profile(self) -> Optional[Dict[str, Any]]:
        if not hasattr(self, "assignment_editor_plan_combo"):
            return None
        try:
            profile_id = int(self.assignment_editor_plan_combo.currentData() or 0)
        except Exception:
            profile_id = 0
        if profile_id <= 0:
            return None
        return next(
            (
                dict(row)
                for row in self.operating_profiles
                if isinstance(row, dict) and int(row.get("id", 0) or 0) == profile_id
            ),
            None,
        )

    @staticmethod
    def _assignment_profiles_for_devices(
        operating_profiles: Sequence[Mapping[str, Any]],
        selected_devices: Sequence[Mapping[str, Any]],
    ) -> List[Dict[str, Any]]:
        """Return only enabled models that are safe for every selected radio.

        Compatibility is resolved before the operator can choose a value.  The
        persistence guard remains authoritative, but an observer should never
        have to select a transmit-capable model merely to learn at Save time
        that the choice is invalid.
        """

        enabled = [
            dict(row)
            for row in operating_profiles
            if isinstance(row, Mapping) and int(row.get("enabled", 1) or 0) == 1
        ]
        observer_selected = any(
            str(row.get("device_class", "") or "").strip().lower() == "observer"
            for row in selected_devices
            if isinstance(row, Mapping)
        )
        if not observer_selected:
            return enabled
        return [row for row in enabled if int(row.get("receive_only", 0) or 0) == 1]

    def _set_assignment_editor_guidance(self, title: str, text: str, level: str = "info") -> None:
        if not hasattr(self, "device_assignments_guidance_card"):
            return
        self._set_guidance_card_state(
            self.device_assignments_guidance_card,
            self.device_assignments_guidance_title_label,
            self.device_assignments_guidance_status_label,
            title=title,
            text=text,
            level=level,
        )

    def _hide_assignment_editor(self) -> None:
        if hasattr(self, "assignment_editor_panel"):
            self.assignment_editor_panel.setVisible(False)
        self.assignment_editor_rows = []
        self._update_device_assignments_guidance_detail()
        self._refresh_fit_content_section_height(getattr(self, "device_assignments_section_group", None))

    def _update_assignment_editor_hint(self) -> None:
        if not hasattr(self, "assignment_editor_hint_label"):
            return
        rows = [row for row in getattr(self, "assignment_editor_rows", []) if isinstance(row, dict)]
        selected_has_observer = any(
            str(row.get("device_class", "") or "").strip().lower() == "observer"
            for row in rows
        )
        selected_profile = self._assignment_editor_selected_profile()
        state = str(self.assignment_editor_state_combo.currentData() or "active").strip().lower()
        bits: List[str] = []
        if selected_has_observer:
            if selected_profile and int(selected_profile.get("receive_only", 0) or 0) != 1:
                bits.append("Observer / SDR radios can only use receive-only Operating Models.")
            else:
                bits.append("Observer / SDR radios require a receive-only Operating Model.")
        if state == "temporary_override":
            bits.append(
                "Temporary Override applies immediately. Timed expiry is metadata only in this checkpoint; restore the default assignment manually when the override ends."
            )
        else:
            bits.append("Active assignments become the current Operating Model for the selected radio immediately.")
        self.assignment_editor_hint_label.setText(" ".join(bits))

    def _show_assignment_editor(
        self,
        selected_devices: List[Dict[str, Any]],
        *,
        source_title: str = "Operating Model Assignment",
    ) -> None:
        selected_rows = [dict(row) for row in selected_devices if isinstance(row, Mapping)]
        observer_selected = any(
            str(row.get("device_class", "") or "").strip().lower() == "observer"
            for row in selected_rows
        )
        enabled_profiles = self._assignment_profiles_for_devices(self.operating_profiles, selected_rows)
        if not enabled_profiles:
            self._set_assignment_editor_guidance(
                source_title,
                (
                    "No enabled receive-only Operating Model is available for this observer / SDR. "
                    "Restore the built-in Receive-only SDR model or create a receive-only model, then try again."
                    if observer_selected
                    else "Create or enable an operating model before assigning it to a radio."
                ),
                "warning",
            )
            return
        self.assignment_editor_rows = selected_rows
        radio_names = [
            str(row.get("device_name", "") or f"Radio {int(row.get('device_profile_id', 0) or 0)}").strip()
            for row in self.assignment_editor_rows
        ]
        radio_names = [name for name in radio_names if name]
        target_text = ", ".join(radio_names[:3])
        if len(radio_names) > 3:
            target_text += f", +{len(radio_names) - 3}"
        count = len(self.assignment_editor_rows)
        assignment_kind = "receive-only Operating Model" if observer_selected else "Operating Model"
        self.assignment_editor_summary_label.setText(
            f"Assign one {assignment_kind} to {count} selected radio{'s' if count != 1 else ''}: "
            f"{target_text or 'selected radio'}."
        )
        self.assignment_editor_plan_label.setText(
            "Receive-only Model:" if observer_selected else "Operating Model:"
        )
        self.assignment_editor_plan_combo.setAccessibleName(
            "Receive-only operating model assignment choice"
            if observer_selected
            else "Operating model assignment choice"
        )

        current_profile_id = 0
        if count == 1:
            try:
                current_profile_id = int(self.assignment_editor_rows[0].get("operating_profile_id") or 0)
            except Exception:
                current_profile_id = 0
        self.assignment_editor_plan_combo.blockSignals(True)
        self.assignment_editor_plan_combo.clear()
        for row in enabled_profiles:
            label = str(row.get("name", "") or "Operating Model")
            if int(row.get("receive_only", 0) or 0) == 1:
                label = f"{label} (receive-only)"
            self.assignment_editor_plan_combo.addItem(label, int(row.get("id", 0) or 0))
        if current_profile_id > 0:
            idx = self.assignment_editor_plan_combo.findData(current_profile_id)
            if idx >= 0:
                self.assignment_editor_plan_combo.setCurrentIndex(idx)
        self.assignment_editor_plan_combo.blockSignals(False)
        if not hasattr(self, "_assignment_editor_plan_signal_connected"):
            self.assignment_editor_plan_combo.currentIndexChanged.connect(self._update_assignment_editor_hint)
            self._assignment_editor_plan_signal_connected = True
        if count == 1:
            state = str(self.assignment_editor_rows[0].get("assignment_state", "") or "active").strip().lower() or "active"
            state_idx = self.assignment_editor_state_combo.findData(state)
            self.assignment_editor_state_combo.setCurrentIndex(state_idx if state_idx >= 0 else 0)
        else:
            self.assignment_editor_state_combo.setCurrentIndex(0)
        if observer_selected:
            active_index = self.assignment_editor_state_combo.findData("active")
            self.assignment_editor_state_combo.setCurrentIndex(active_index if active_index >= 0 else 0)
        self.assignment_editor_state_combo.setEnabled(not observer_selected)
        self.assignment_editor_state_combo.setToolTip(
            "Receive-only SDR assignments are active configuration; they do not grant scheduler, QSY, or transmit control."
            if observer_selected
            else "Choose whether this assignment is normal or a temporary override."
        )
        self.assignment_editor_ends_edit.setVisible(not observer_selected)
        if self.assignment_editor_ends_label is not None:
            self.assignment_editor_ends_label.setVisible(not observer_selected)
        self.assignment_editor_reason_edit.clear()
        self.assignment_editor_ends_edit.clear()
        self.assignment_editor_panel.setVisible(True)
        self._update_assignment_editor_hint()
        self._set_assignment_editor_guidance(
            source_title,
            "Review the assignment details in this panel, then save or cancel without leaving the Settings workspace.",
            "info",
        )
        self._refresh_fit_content_section_height(getattr(self, "device_assignments_section_group", None))

    def _save_assignment_editor(self) -> None:
        selected = [row for row in getattr(self, "assignment_editor_rows", []) if isinstance(row, dict)]
        if not selected:
            self._set_assignment_editor_guidance(
                "Operating Model Assignment",
                "Select one or more radios before saving an operating model assignment.",
                "warning",
            )
            return
        try:
            profile_id = int(self.assignment_editor_plan_combo.currentData() or 0)
        except Exception:
            profile_id = 0
        if profile_id <= 0:
            self._set_assignment_editor_guidance("Operating Model Assignment", "Select an Operating Model.", "warning")
            return
        selected_profile = self._assignment_editor_selected_profile()
        selected_has_observer = any(
            str(row.get("device_class", "") or "").strip().lower() == "observer"
            for row in selected
        )
        if selected_has_observer and int((selected_profile or {}).get("receive_only", 0) or 0) != 1:
            self._set_assignment_editor_guidance(
                "Operating Model Assignment",
                "Observer / SDR radios can only be assigned receive-only operating models.",
                "warning",
            )
            return
        state = str(self.assignment_editor_state_combo.currentData() or "active").strip().lower() or "active"
        reason_value = self.assignment_editor_reason_edit.text().strip()
        if state == "temporary_override" and not reason_value:
            reason_value = "Temporary override from Settings."
        ends_value = self.assignment_editor_ends_edit.text().strip()
        try:
            for row in selected:
                self.multi_radio_store.set_device_operating_profile(
                    int(row.get("device_profile_id", 0) or 0),
                    profile_id,
                    assignment_state=state,
                    reason=reason_value,
                    ends_utc=ends_value,
                )
        except ValueError as exc:
            self._set_assignment_editor_guidance("Operating Model Assignment", str(exc), "warning")
            return
        except Exception:
            log.exception("Failed updating radio operating model assignments.")
            self._set_assignment_editor_guidance(
                "Operating Model Assignment",
                "Unable to update the selected operating model assignment.",
                "danger",
            )
            return
        self.assignment_editor_panel.setVisible(False)
        self.assignment_editor_rows = []
        self._refresh_multi_radio_tables()
        self._refresh_fit_content_section_height(getattr(self, "device_assignments_section_group", None))
        self._emit_device_profiles_changed()
        self._set_save_button_state("info" if self._settings_dirty else "success")
        self._publish_settings_action_feedback(
            status="succeeded",
            summary=f"Updated operating model assignment for {len(selected)} radio{'s' if len(selected) != 1 else ''}.",
            action_type="operating_model_assignment",
        )

    def _assign_operating_profile_to_selected_devices(self) -> None:
        selected = self._selected_assignment_rows()
        if not selected:
            self._set_assignment_editor_guidance(
                "Operating Model Assignment",
                "Select one or more radios in the table before assigning an Operating Model.",
                "warning",
            )
            return
        self._show_assignment_editor(selected)

    def _restore_default_operating_profile_for_selected_devices(self) -> None:
        selected = self._selected_assignment_rows()
        if not selected:
            QMessageBox.information(self, "Operating Model Assignment", "Select one or more radios to restore.")
            return
        try:
            for row in selected:
                self.multi_radio_store.restore_default_operating_profile(int(row.get("device_profile_id", 0) or 0))
        except ValueError as exc:
            QMessageBox.warning(self, "Operating Model Assignment", str(exc))
            self._refresh_multi_radio_tables()
            return
        except Exception:
            log.exception("Failed restoring default operating model.")
            QMessageBox.warning(self, "Operating Model Assignment", "Unable to restore the default operating model assignment.")
            return
        self._refresh_multi_radio_tables()
        self._emit_device_profiles_changed()
        self._set_save_button_state("info" if self._settings_dirty else "success")

    def _assign_schedule_to_selected_radios(self) -> None:
        selected = self._selected_device_profiles_as_assignment_rows()
        if not selected:
            self._set_assignment_editor_guidance(
                "Operating Model Assignment",
                "Select one or more radios before assigning an Operating Model.",
                "warning",
            )
            return
        self.show_settings_context("radios", health_key="operating_model_assignments")
        self._show_assignment_editor(selected, source_title="Operating Model Assignment")

    def _restore_schedule_for_selected_radios(self) -> None:
        selected = self._selected_device_profiles()
        if not selected:
            QMessageBox.information(self, "Operating Model Assignment", "Select one or more radios to restore.")
            return
        try:
            for row in selected:
                self.multi_radio_store.restore_default_operating_profile(int(row.get("id", 0) or 0))
        except ValueError as exc:
            QMessageBox.warning(self, "Operating Model Assignment", str(exc))
            self._refresh_multi_radio_tables()
            return
        except Exception:
            log.exception("Failed restoring operating model from radio profiles.")
            QMessageBox.warning(self, "Operating Model Assignment", "Unable to restore the selected operating model assignments.")
            return
        self._refresh_multi_radio_tables()
        self._emit_device_profiles_changed()
        self._set_save_button_state("info" if self._settings_dirty else "success")

    def _open_temporary_profile_swap_dialog(self, target_row: Dict[str, Any]) -> Optional[Dict[str, Any]]:
        primary_row = next(
            (
                row
                for row in self.device_assignments
                if isinstance(row, dict) and int(row.get("runtime_primary", 0) or 0) == 1
            ),
            None,
        )
        if not isinstance(primary_row, dict):
            QMessageBox.warning(self, "Temporary Model Swap", "The current Station Default radio assignment could not be resolved.")
            return None
        primary_profile = self._operating_profile_by_id(int(primary_row.get("operating_profile_id", 0) or 0))
        allow_carry = bool(primary_profile and int(primary_profile.get("allow_profile_swap", 0) or 0) == 1)

        dlg = QDialog(self)
        dlg.setWindowTitle("Temporary Model Swap")
        dlg.resize(560, 0)
        layout = QVBoxLayout(dlg)
        form = QFormLayout()
        layout.addLayout(form)

        summary_label = QLabel(
            f"Temporarily move the Station Default runtime from "
            f"{str(primary_row.get('device_name', '') or 'current primary')} to "
            f"{str(target_row.get('device_name', '') or 'selected target')}."
        )
        summary_label.setWordWrap(True)
        form.addRow("", summary_label)

        form.addRow("Current Primary:", QLabel(str(primary_row.get("device_name", "") or "")))
        form.addRow("Primary Assigned Model:", QLabel(str(primary_row.get("operating_profile_name", "") or "Unassigned")))
        form.addRow("Target Radio:", QLabel(str(target_row.get("device_name", "") or "")))
        form.addRow("Target Assigned Model:", QLabel(str(target_row.get("operating_profile_name", "") or "Unassigned")))

        mode_combo = QComboBox()
        mode_combo.addItem("Use target radio assigned model (Recommended)", "use_target_profile")
        if allow_carry:
            mode_combo.addItem("Carry current Station Default assigned model", "carry_primary_profile")
        form.addRow("Swap Mode:", mode_combo)

        reason_edit = QLineEdit()
        reason_edit.setPlaceholderText("Optional operator note")
        reason_edit.setText(
            f"Temporary model swap {str(primary_row.get('device_name', '') or 'primary')} -> {str(target_row.get('device_name', '') or 'target')}"
        )
        form.addRow("Reason:", reason_edit)

        ends_edit = QLineEdit()
        ends_edit.setPlaceholderText("Optional UTC metadata only; no automatic expiry in this checkpoint")
        form.addRow("Ends UTC:", ends_edit)

        info_label = QLabel()
        info_label.setWordWrap(True)
        form.addRow("", info_label)

        def _update_hint() -> None:
            mode = str(mode_combo.currentData() or "use_target_profile").strip().lower()
            if mode == "carry_primary_profile":
                carried_name = str((primary_profile or {}).get("name", "") or "Current Station Default Assigned Model")
                info_label.setText(
                    f"{carried_name} will be copied onto the target radio as a temporary override. "
                    "Restore Swap returns the target radio to its prior effective assignment."
                )
            elif not allow_carry:
                info_label.setText(
                    "The current Station Default assigned model does not allow carried swaps, so this workflow keeps the target radio's existing effective assigned model."
                )
            else:
                info_label.setText(
                    "This swap changes the Station Default radio temporarily but leaves the target radio's current effective assigned model in place."
                )

        mode_combo.currentIndexChanged.connect(_update_hint)
        _update_hint()

        buttons = QDialogButtonBox(QDialogButtonBox.Save | QDialogButtonBox.Cancel)
        layout.addWidget(buttons)

        out: Dict[str, Any] = {}

        def _save() -> None:
            out.update(
                {
                    "mode": str(mode_combo.currentData() or "use_target_profile").strip().lower() or "use_target_profile",
                    "reason": reason_edit.text().strip(),
                    "ends_utc": ends_edit.text().strip(),
                }
            )
            dlg.accept()

        buttons.accepted.connect(_save)
        buttons.rejected.connect(dlg.reject)
        if dlg.exec() != QDialog.Accepted:
            return None
        return out if out else None

    def _start_temporary_profile_swap(self) -> None:
        if isinstance(self.active_profile_swap, dict) and self.active_profile_swap:
            QMessageBox.information(self, "Temporary Model Swap", "A temporary model swap is already active. Restore it before starting another.")
            return
        selected = self._selected_assignment_rows()
        if not selected:
            QMessageBox.information(self, "Temporary Model Swap", "Select one active non-primary radio to use as the temporary model swap target.")
            return
        if len(selected) != 1:
            QMessageBox.warning(self, "Temporary Model Swap", "Please select exactly one active non-primary radio as the temporary model swap target.")
            return
        target_row = selected[0]
        if int(target_row.get("runtime_primary", 0) or 0) == 1:
            QMessageBox.information(self, "Temporary Model Swap", "The selected radio is already the Station Default runtime.")
            return
        if str(target_row.get("device_class", "") or "").strip().lower() == "observer":
            QMessageBox.warning(self, "Temporary Model Swap", "Observer / SDR radios cannot be used as temporary model swap targets.")
            return
        if int(target_row.get("runtime_active", 0) or 0) != 1:
            QMessageBox.warning(self, "Temporary Model Swap", "The temporary model swap target must already be active.")
            return
        values = self._open_temporary_profile_swap_dialog(target_row)
        if not values:
            return
        try:
            self.multi_radio_store.start_temporary_profile_swap(
                int(target_row.get("device_profile_id", 0) or 0),
                mode=str(values.get("mode", "use_target_profile") or "use_target_profile"),
                reason=str(values.get("reason", "") or ""),
                ends_utc=str(values.get("ends_utc", "") or ""),
            )
        except ValueError as exc:
            QMessageBox.warning(self, "Temporary Model Swap", str(exc))
            self._refresh_multi_radio_tables()
            return
        except Exception:
            log.exception("Failed starting temporary profile swap.")
            QMessageBox.warning(self, "Temporary Model Swap", "Unable to start the temporary model swap.")
            return
        self._refresh_multi_radio_tables()
        self._emit_device_profiles_changed()
        self._set_save_button_state("info" if self._settings_dirty else "success")

    def _restore_temporary_profile_swap(self) -> None:
        active_swap = dict(self.active_profile_swap or {})
        if not active_swap:
            QMessageBox.information(self, "Restore Swap", "No temporary model swap is currently active.")
            return
        source_name = str(active_swap.get("source_device_name", "") or "").strip() or "previous primary"
        target_name = str(active_swap.get("target_device_name", "") or "").strip() or "temporary target"
        confirm = QMessageBox.question(
            self,
            "Restore Swap",
            f"Restore the Station Default runtime from {target_name} back to {source_name}?",
            QMessageBox.Yes | QMessageBox.No,
            QMessageBox.Yes,
        )
        if confirm != QMessageBox.Yes:
            return
        try:
            self.multi_radio_store.restore_temporary_profile_swap()
        except ValueError as exc:
            QMessageBox.warning(self, "Restore Swap", str(exc))
            self._refresh_multi_radio_tables()
            return
        except Exception:
            log.exception("Failed restoring temporary profile swap.")
            QMessageBox.warning(self, "Restore Swap", "Unable to restore the temporary model swap.")
            return
        self._refresh_multi_radio_tables()
        self._emit_device_profiles_changed()
        self._set_save_button_state("info" if self._settings_dirty else "success")

    def _confirm_runtime_projection_override(self, action_name: str) -> bool:
        if not self._settings_dirty:
            return True
        confirm = QMessageBox.question(
            self,
            action_name,
            "Unsaved Settings changes are present.\n\n"
            "Continuing will replace the visible compatibility backend and endpoint fields with the selected device "
            "profile projection.\n\nContinue?",
            QMessageBox.Yes | QMessageBox.No,
            QMessageBox.No,
        )
        return confirm == QMessageBox.Yes

    @staticmethod
    def _device_profile_dialog_title(existing: Optional[Dict[str, Any]] = None) -> str:
        return "Radio Details" if existing else "Guided Add Radio"

    @staticmethod
    def _device_profile_dialog_intro(existing: Optional[Dict[str, Any]] = None) -> str:
        if existing:
            return (
                "Detailed editor for the selected radio while the guided in-page settings are being completed. "
                "Use the Radio Settings tasks first when possible."
            )
        return (
            "Set up a new radio one step at a time: choose the radio identity, pick the software used by that radio, "
            "enter the connection details that matter, and review readiness before saving."
        )

    @staticmethod
    def _device_profile_dialog_save_text(existing: Optional[Dict[str, Any]] = None) -> str:
        return "Save Changes" if existing else "Save Radio and Software"

    def _present_guided_stale_review_recovery(
        self,
        detail: str = "",
        *,
        parent: QWidget | None = None,
    ) -> str:
        """Present the non-mutating recovery route for a stale reviewed plan.

        The transaction owner performs the authoritative revalidation.  This
        helper only translates that outcome into the two task-oriented places
        where an operator can resume the retained draft.
        """

        box = QMessageBox(parent or self)
        box.setWindowTitle("Review Changed")
        box.setAccessibleName("Guided radio review changed")
        box.setIcon(QMessageBox.Warning)
        box.setText(
            "Software availability changed after this setup was reviewed. Nothing was changed."
        )
        recovery_detail = str(detail or "").strip()
        box.setInformativeText(
            (recovery_detail + "\n\n" if recovery_detail else "")
            + "Return to Software to refresh the affected choice, then continue to Review & Save again."
        )
        software_button = box.addButton("Review Software", QMessageBox.ActionRole)
        review_button = box.addButton("Review Again", QMessageBox.ActionRole)
        cancel_button = box.addButton(QMessageBox.Cancel)
        software_button.setAccessibleName("Return to guided Software step")
        review_button.setAccessibleName("Return to guided Review and Save step")
        cancel_button.setAccessibleName("Close stale review recovery")
        box.setDefaultButton(software_button)
        box.exec()
        clicked = box.clickedButton()
        if clicked is software_button:
            return "software"
        if clicked is review_button:
            return "review"
        return ""

    def _open_device_profile_dialog(
        self,
        existing: Optional[Dict[str, Any]] = None,
        *,
        initial_step: str = "",
        retry_draft: Optional[Mapping[str, Any]] = None,
    ) -> Optional[Dict[str, Any]]:
        dlg = QDialog(self)
        profile_seed: Mapping[str, Any] = retry_draft or existing or {}
        guided_identity_radio_key = str(
            profile_seed.get("system_key") or f"guided-radio-{uuid.uuid4().hex}"
        ).strip()
        try:
            guided_identity_generation = (
                self.multi_radio_store.radio_software_identity_generation(
                    int(profile_seed.get("id", 0) or 0)
                )
                if int(profile_seed.get("id", 0) or 0) > 0
                else 0
            )
        except Exception:
            log.exception("Failed loading the guided software identity generation.")
            guided_identity_generation = 0
        retry_software_drafts = profile_seed.get("guided_software_instance_drafts", {})
        if isinstance(retry_software_drafts, Mapping):
            setattr(
                dlg,
                "_guided_software_instance_drafts",
                {
                    str(family): dict(value)
                    for family, value in retry_software_drafts.items()
                    if isinstance(value, Mapping)
                },
            )
        guided_discovery_session_key = f"guided-radio-{uuid.uuid4().hex}"
        guided_discovery_generation = 0
        guided_discovery_revision = 0
        dlg_title = self._device_profile_dialog_title(existing)
        dlg.setWindowTitle(dlg_title)
        dlg.setAccessibleName(dlg_title)
        dlg.setSizeGripEnabled(True)
        dlg.setMinimumSize(0, 0)
        # Load one bounded, immutable authority snapshot for the dialog.  The
        # previous per-family helper re-read every manifest three times, which
        # needlessly increased Add Radio startup latency.
        try:
            guided_manifests = self.multi_radio_store.list_software_instance_manifests()
        except Exception:
            log.exception("Failed loading guided software manifests.")
            guided_manifests = []
        try:
            guided_profiles = self.multi_radio_store.list_device_profiles()
        except Exception:
            log.exception("Failed loading guided software radio links.")
            guided_profiles = []
        try:
            guided_varac_cluster_rows = self.multi_radio_store.list_varac_clusters()
            guided_varac_membership_rows = self.multi_radio_store.list_varac_cluster_members()
            guided_varac_topology_snapshot_available = True
        except Exception:
            # The arrangement presentation must fail closed.  An unavailable
            # read-only cluster snapshot is not evidence that a cluster is
            # absent, so only the safe standalone preparation route remains.
            log.exception("Failed loading guided VarAC arrangement snapshot.")
            guided_varac_cluster_rows = []
            guided_varac_membership_rows = []
            guided_varac_topology_snapshot_available = False
        guided_linked_instance_ids = self._linked_software_instance_ids(guided_profiles)
        guided_saved_instance_rows = {
            "js8call": self._enrich_software_instance_rows(
                "js8call", self.multi_radio_store.list_js8_instances(), guided_manifests
            ),
            "fast_light": self._enrich_software_instance_rows(
                "fast_light", self.multi_radio_store.list_fast_light_configs(), guided_manifests
            ),
            "varac": self._enrich_software_instance_rows(
                "varac", self.multi_radio_store.list_varac_nodes(), guided_manifests
            ),
        }
        guided_instance_inventory_generation = 0
        guided_instance_inventory_snapshot = build_guided_instance_inventory(
            guided_saved_instance_rows,
            linked_ids_by_family=guided_linked_instance_ids,
            generation=guided_instance_inventory_generation,
        )

        def _refresh_guided_instance_inventory(
            retained_drafts: Mapping[str, Mapping[str, Any]] | None = None,
        ):
            nonlocal guided_instance_inventory_generation, guided_instance_inventory_snapshot
            guided_instance_inventory_generation += 1
            guided_instance_inventory_snapshot = build_guided_instance_inventory(
                guided_saved_instance_rows,
                retained_drafts=retained_drafts,
                linked_ids_by_family=guided_linked_instance_ids,
                generation=guided_instance_inventory_generation,
            )
            return guided_instance_inventory_snapshot

        def _guided_dialog_initial_size(
            preferred: QSize | None = None,
            *,
            screen_margin: int = 40,
        ) -> QSize:
            preferred = preferred or QSize(760, 720)
            app = QApplication.instance()
            screen = app.primaryScreen() if app is not None else None
            if screen is None:
                return preferred
            available = screen.availableGeometry().size()
            return QSize(
                min(preferred.width(), max(1, available.width() - int(screen_margin))),
                min(preferred.height(), max(1, available.height() - int(screen_margin))),
            )

        dlg.resize(_guided_dialog_initial_size())
        layout = QVBoxLayout(dlg)
        intro = QLabel(self._device_profile_dialog_intro(existing))
        intro.setAccessibleName(f"{dlg_title} guidance")
        intro.setWordWrap(True)
        layout.addWidget(intro)

        scroll = QScrollArea(dlg)
        scroll.setObjectName("guidedRadioSetupBodyScroll")
        scroll.setAccessibleName("Guided radio setup body")
        scroll.setWidgetResizable(True)
        scroll.setFrameShape(QFrame.NoFrame)
        scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        layout.addWidget(scroll, 1)

        body = QWidget()
        scroll.setWidget(body)
        body_layout = QVBoxLayout(body)
        body_layout.setContentsMargins(0, 0, 0, 0)
        body_layout.setSpacing(10)
        theme = resolve_theme(self.settings)

        catalog_payload = load_radio_catalog()
        catalog_entries = list(catalog_payload.get("entries", []) or [])
        catalog_source = str(catalog_payload.get("source", "static-fallback") or "static-fallback")
        radio_model_prompt = "Select or search for a radio model"
        row_labels: Dict[QWidget, QWidget] = {}

        def _show_help(btn: QWidget, text: str) -> None:
            QToolTip.showText(btn.mapToGlobal(btn.rect().bottomLeft()), text, btn)

        def _make_help_label(text: str, help_text: str = "") -> QWidget:
            wrap = QWidget()
            row = QHBoxLayout(wrap)
            row.setContentsMargins(0, 0, 0, 0)
            row.setSpacing(4)
            label = QLabel(text)
            label.setWordWrap(True)
            label.setSizePolicy(QSizePolicy.Preferred, QSizePolicy.Preferred)
            row.addWidget(label)
            if help_text:
                help_btn = QPushButton("i", wrap)
                help_btn.setCheckable(False)
                help_btn.setText("?")
                help_side = button_height_for_font(help_btn, vertical_padding=4, floor=20)
                help_btn.setFixedSize(help_side, help_side)
                help_btn.setToolTip(help_text)
                help_btn.setCursor(Qt.PointingHandCursor)
                help_btn.setStyleSheet(
                    "QPushButton {"
                    " border: 1px solid palette(mid);"
                    f" border-radius: {max(1, help_side // 2)}px;"
                    " padding: 0px;"
                    " font-weight: bold;"
                    f" min-width: {help_side}px;"
                    f" min-height: {help_side}px;"
                    "}"
                    "QPushButton:hover {"
                    " background: palette(base);"
                    "}"
                )
                help_btn.clicked.connect(lambda _checked=False, b=help_btn, t=help_text: _show_help(b, t))
                row.addWidget(help_btn)
            row.addStretch(1)
            return wrap

        def _add_form_row(form_layout: QFormLayout, label_text: str, field_widget: QWidget, help_text: str = "") -> None:
            field_widget.setSizePolicy(QSizePolicy.Expanding, field_widget.sizePolicy().verticalPolicy())
            label_widget = _make_help_label(label_text, help_text) if label_text else QWidget()
            if label_text:
                row_labels[field_widget] = label_widget
                form_layout.addRow(label_widget, field_widget)
            else:
                form_layout.addRow("", field_widget)

        def _add_full_width_row(form_layout: QFormLayout, field_widget: QWidget) -> None:
            field_widget.setSizePolicy(QSizePolicy.Expanding, field_widget.sizePolicy().verticalPolicy())
            form_layout.addRow(field_widget)

        def _set_form_row_label_text(field_widget: QWidget, text: str) -> None:
            """Update a help-label row without replacing its accessible help action."""

            label_widget = row_labels.get(field_widget)
            if isinstance(label_widget, QLabel):
                label_widget.setText(text)
                return
            if isinstance(label_widget, QWidget):
                labels = label_widget.findChildren(QLabel)
                if labels:
                    labels[0].setText(text)

        def _configure_combo_width(combo: QComboBox, minimum: int = 220) -> None:
            combo.setSizeAdjustPolicy(QComboBox.AdjustToMinimumContentsLengthWithIcon)
            combo.setMinimumContentsLength(max(12, min(28, int(minimum / 10))))
            combo.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
            fm = combo.fontMetrics()
            widest = minimum
            for idx in range(combo.count()):
                widest = max(widest, fm.horizontalAdvance(combo.itemText(idx)) + 56)
            try:
                combo.view().setMinimumWidth(min(max(widest + 24, minimum), 520))
            except Exception:
                pass

        def _configure_port_edit(edit: QLineEdit) -> None:
            edit.setMaximumWidth(110)
            edit.setSizePolicy(QSizePolicy.Maximum, QSizePolicy.Fixed)

        def _make_browse_row(
            edit: QLineEdit,
            *,
            title: str,
            mode: str = "file",
            file_filter: str = "All Files (*)",
        ) -> QWidget:
            edit.setMinimumWidth(0)
            edit.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
            browse_btn = QPushButton("Browse")
            browse_btn.setMinimumWidth(86)
            browse_btn.setSizePolicy(QSizePolicy.Fixed, QSizePolicy.Fixed)
            browse_btn.setToolTip(f"Choose {title.lower()} if CommsPlan did not detect the right location.")
            row = QHBoxLayout()
            row.setContentsMargins(0, 0, 0, 0)
            row.setSpacing(8)
            row.addWidget(edit, 1)
            row.addWidget(browse_btn)
            wrap = QWidget()
            wrap.setLayout(row)

            def _browse() -> None:
                start = edit.text().strip() or str(Path.home())
                if mode == "folder" or (mode == "app" and platform.system() == "Darwin"):
                    chosen = QFileDialog.getExistingDirectory(self, title, start)
                else:
                    chosen, _selected_filter = QFileDialog.getOpenFileName(self, title, start, file_filter)
                if chosen:
                    edit.setText(chosen)
                    _update_dialog_readiness()

            browse_btn.clicked.connect(_browse)
            return wrap

        def _configure_guided_form(form_layout: QFormLayout) -> None:
            form_layout.setFieldGrowthPolicy(QFormLayout.ExpandingFieldsGrow)
            form_layout.setRowWrapPolicy(QFormLayout.WrapLongRows)
            form_layout.setLabelAlignment(Qt.AlignLeft | Qt.AlignTop)
            form_layout.setFormAlignment(Qt.AlignLeft | Qt.AlignTop)
            form_layout.setHorizontalSpacing(12)
            form_layout.setVerticalSpacing(8)

        def _make_section(title: str, help_text: str = "") -> tuple[QGroupBox, QFormLayout]:
            group = QGroupBox(title)
            group_layout = QVBoxLayout(group)
            group_layout.setContentsMargins(10, 10, 10, 10)
            group_layout.setSpacing(8)
            if help_text:
                help_label = QLabel(help_text)
                help_label.setWordWrap(True)
                group_layout.addWidget(help_label)
            form_layout = QFormLayout()
            _configure_guided_form(form_layout)
            group_layout.addLayout(form_layout)
            body_layout.addWidget(group)
            return group, form_layout

        requested_initial_step = str(initial_step or "").strip().lower()
        guided_wizard_step_id = (
            requested_initial_step
            if existing
            and requested_initial_step in {"radio", "model", "software", "connection", "guard", "schedule", "review"}
            else "radio"
        )
        # The shared guided-setup contract owns these stable positions.  Do
        # not insert, remove, or renumber steps locally when the radio role
        # changes; only the role-specific content and descriptive title adapt.
        guided_wizard_steps: Tuple[Tuple[str, str], ...] = tuple(
            (step_id, "CommsPlan Behavior" if step_id == "model" else label)
            for step_id, label in guided_setup_wizard_view("radio").steps
        )
        guided_wizard_max_index_seen = (
            len(guided_wizard_steps) - 1 if existing or retry_draft else 0
        )
        guided_wizard_group = QGroupBox("Guided Setup")
        guided_wizard_group.setObjectName("guidedSetupWizard")
        # This is a navigation header, not page content.  Keep it at its
        # natural height when the dialog is maximized and give the remaining
        # space to the single scrolling body below.
        guided_wizard_group.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
        guided_wizard_layout = QVBoxLayout(guided_wizard_group)
        guided_wizard_layout.setContentsMargins(10, 8, 10, 8)
        guided_wizard_layout.setSpacing(8)
        guided_wizard_buttons_row = QGridLayout()
        guided_wizard_buttons_row.setContentsMargins(0, 0, 0, 0)
        guided_wizard_buttons_row.setHorizontalSpacing(6)
        guided_wizard_buttons_row.setVerticalSpacing(6)
        guided_wizard_buttons: Dict[str, QPushButton] = {}
        for idx, (step_id, label) in enumerate(guided_wizard_steps, start=1):
            btn = QPushButton(f"{idx}. {label}")
            btn.setObjectName(f"guidedWizardStep_{step_id}")
            btn.setCheckable(True)
            btn.setAccessibleName(f"Guided setup step {idx}: {label}")
            btn.setToolTip(f"Show the {label} setup step.")
            btn.setMinimumWidth(0)
            btn.setMinimumHeight(button_height_for_font(btn))
            btn.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
            guided_wizard_buttons[step_id] = btn
            guided_wizard_buttons_row.addWidget(btn, (idx - 1) // 3, (idx - 1) % 3)
        for col in range(3):
            guided_wizard_buttons_row.setColumnStretch(col, 1)
        guided_wizard_layout.addLayout(guided_wizard_buttons_row)
        guided_wizard_detail_label = QLabel("Start with the radio model and setup type.")
        guided_wizard_detail_label.setObjectName("guidedWizardDetail")
        guided_wizard_detail_label.setWordWrap(True)
        guided_wizard_layout.addWidget(guided_wizard_detail_label)
        guided_wizard_back_btn = QPushButton("Back")
        guided_wizard_back_btn.setObjectName("guidedWizardBack")
        guided_wizard_back_btn.setAccessibleName("Previous guided setup step")
        guided_wizard_next_btn = QPushButton("Next")
        guided_wizard_next_btn.setObjectName("guidedWizardNext")
        guided_wizard_next_btn.setAccessibleName("Next guided setup step")
        # The purpose and step controls are a fixed header.  The current step
        # body alone owns vertical scrolling; Back/Next are placed in the fixed
        # action footer below after the button box is created.
        layout.insertWidget(layout.indexOf(scroll), guided_wizard_group)

        readiness_card = QFrame()
        readiness_card.setFrameShape(QFrame.StyledPanel)
        readiness_card_layout = QVBoxLayout(readiness_card)
        readiness_card_layout.setContentsMargins(12, 10, 12, 10)
        readiness_card_layout.setSpacing(6)
        readiness_title = QLabel("Live Radio Readiness")
        readiness_title_font = readiness_title.font()
        readiness_title_font.setBold(True)
        readiness_title.setFont(readiness_title_font)
        readiness_card_layout.addWidget(readiness_title)
        readiness_intro = QLabel(
            "CommsPlan checks this radio as you edit it so the next setup step is easier to spot before you save."
        )
        readiness_intro.setObjectName("readinessIntro")
        readiness_intro.setWordWrap(True)
        readiness_card_layout.addWidget(readiness_intro)
        dialog_readiness_status = QLabel()
        dialog_readiness_status.setWordWrap(True)
        dialog_readiness_detail = QLabel()
        dialog_readiness_detail.setWordWrap(True)
        readiness_card_layout.addWidget(dialog_readiness_status)
        readiness_card_layout.addWidget(dialog_readiness_detail)
        body_layout.addWidget(readiness_card)

        identity_group, identity_form = _make_section(
            "Radio Identity",
            "Start with the actual radio model, then give the radio a station-friendly name if you want one.",
        )
        software_group = QGroupBox("Software Stack and Guidance")
        software_group_layout = QVBoxLayout(software_group)
        software_group_layout.setContentsMargins(10, 10, 10, 10)
        software_group_layout.setSpacing(8)
        body_layout.addWidget(software_group)
        software_form = QFormLayout()
        _configure_guided_form(software_form)
        software_group_layout.addLayout(software_form)

        # Observer/SDR profiles use a receive-only stack rather than the
        # transceiver software checklist below.  Keep this in the same guided
        # Software step so the operator can choose the receiver application
        # and its launch behavior once, before testing the endpoint.
        receiver_stack_group = QGroupBox("Receive-only software stack")
        receiver_stack_group.setObjectName("guidedReceiverSoftwareStack")
        receiver_stack_layout = QFormLayout(receiver_stack_group)
        _configure_guided_form(receiver_stack_layout)
        receiver_stack_hint = QLabel(
            "Choose the receiver application and any radio-owned receive software for this SDR. "
            "The SDR remains receive-only: these choices never enable PTT, transmit, QSY, or frequency scheduling."
        )
        receiver_stack_hint.setObjectName("guidedReceiverSoftwareStackHint")
        receiver_stack_hint.setWordWrap(True)
        _add_full_width_row(receiver_stack_layout, receiver_stack_hint)
        existing_receiver_bundle: Dict[str, Any] = {}
        existing_receiver_launch_item: Dict[str, Any] = {}
        try:
            existing_radio_id = int((profile_seed or {}).get("id", 0) or 0)
        except (TypeError, ValueError):
            existing_radio_id = 0
        if existing_radio_id > 0 and str((profile_seed or {}).get("device_class", "") or "").strip().lower() == "observer":
            try:
                existing_receiver_bundle = dict(
                    self.launch_orchestrator.get_radio_launch_bundle(existing_radio_id) or {}
                )
            except Exception:
                log.debug("Unable to load the existing receiver launch bundle.", exc_info=True)
            for launch_item in existing_receiver_bundle.get("items", []):
                if isinstance(launch_item, dict) and str(launch_item.get("name", "") or "").strip() == "SDR++":
                    existing_receiver_launch_item = dict(launch_item)
                    break

        receiver_application_combo = QComboBox()
        receiver_application_combo.setObjectName("guidedReceiverLaunchApplication")
        receiver_application_combo.addItem("No application launch", "")
        receiver_application_combo.addItem("SDR++", "SDR++")
        receiver_application_combo.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
        _add_form_row(
            receiver_stack_layout,
            "Receiver application:",
            receiver_application_combo,
            "Select the receive-only application CommsPlan should launch for this profile.",
        )
        existing_receiver_launch_target = str(
            existing_receiver_launch_item.get("launch_path_override", "")
            or existing_receiver_launch_item.get("launch_command_override", "")
            or (profile_seed or {}).get("launch_path", "")
            or ""
        ).strip()
        receiver_launch_path_edit = QLineEdit(existing_receiver_launch_target)
        receiver_launch_path_edit.setObjectName("guidedReceiverLaunchPath")
        receiver_launch_path_wrap = _make_browse_row(
            receiver_launch_path_edit,
            title="Select receiver application",
            mode="app",
        )
        _add_form_row(
            receiver_stack_layout,
            "Launch target:",
            receiver_launch_path_wrap,
            "Use the suggested SDR++ command, or choose its executable/application bundle. CommsPlan stores it only in this receiver's launch recipe.",
        )
        receiver_launch_enabled_chk = QCheckBox("Launch this receiver application with CommsPlan")
        receiver_launch_enabled_chk.setObjectName("guidedReceiverLaunchEnabled")
        receiver_launch_enabled_chk.setChecked(
            bool(
                existing_receiver_bundle.get("launch_enabled", False)
                and existing_receiver_launch_item.get("enabled", True)
                and existing_receiver_launch_item.get("startup", True)
            )
            if existing_receiver_launch_item
            else bool((profile_seed or {}).get("launch_enabled", 0))
        )
        receiver_launch_enabled_chk.setToolTip("Start the selected receive-only application when this receiver is launched.")
        _add_full_width_row(receiver_stack_layout, receiver_launch_enabled_chk)
        software_group_layout.addWidget(receiver_stack_group)
        connection_group, connection_form = _make_section(
            "Connections",
            "Only the fields that matter for the selected role, backend, and software are shown.",
        )
        connection_status_label = QLabel()
        connection_status_label.setObjectName("guidedConnectionStatus")
        connection_status_label.setWordWrap(True)
        _add_full_width_row(connection_form, connection_status_label)
        managed_recipe_summary = QLabel()
        managed_recipe_summary.setObjectName("guidedManagedRecipeSummary")
        managed_recipe_summary.setAccessibleName("Resolved managed software details")
        managed_recipe_summary.setWordWrap(True)
        _add_full_width_row(connection_form, managed_recipe_summary)
        connection_responsibility_group = QGroupBox("Connection responsibilities")
